// ===== CHEM 1211 Exam 2 question bank =====
// Every correct option is stored at index 0 (a:0). buildPerm() shuffles options at runtime, so the stored
// position is never what the student sees. Numeric answers were computed in Python, not by hand.
// Sources: Exam 2 study guide (21 focus topics), Handouts 7-12, Chapter 3 and Chapter 4 Part 1 Review
// Worksheet keys, Sep 9 to Oct 9 decks, and the two Chapter 3 videos.

// Orbital-box diagram: OB([['1s','ud'],['2s','ud'],['2p','ud u 0']]) ; ud = pair, u = one up, 0 = empty.
const OB = rows => `<div class="ob">` + rows.map(([lab, cells]) =>
  `<span class="ob-sub"><span class="ob-boxes">` + cells.split(' ').map(c =>
    `<span class="ob-box">${c === 'ud' ? '&uarr;&darr;' : c === 'u' ? '&uarr;' : c === 'uu' ? '&uarr;&uarr;' : ''}</span>`).join('') +
  `</span><span class="ob-lab">${lab}</span></span>`).join('') + `</div>`;

const Q = [
// ===== 1. Light and the EM spectrum =====
{chId:'light',ch:'Light and the EM Spectrum',q:"Order the seven regions of the electromagnetic spectrum from LOWEST to HIGHEST energy.",o:["radio, microwave, infrared, visible, ultraviolet, X-ray, gamma","gamma, X-ray, ultraviolet, visible, infrared, microwave, radio","radio, infrared, microwave, visible, X-ray, ultraviolet, gamma","microwave, radio, infrared, visible, ultraviolet, gamma, X-ray","visible, infrared, ultraviolet, radio, microwave, X-ray, gamma"],a:0,lec:'Sep 16 lecture: the EM spectrum',e:"His mnemonic is <strong>RaMIVUXGam</strong>: Radio, Microwave, Infrared, Visible, UV, X-ray, Gamma. Left to right, frequency and energy go <strong>up</strong> and wavelength goes <strong>down</strong>. The study guide says you must know the names AND the energy order."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Which region of the electromagnetic spectrum has the LONGEST wavelength?",o:["radio waves","gamma rays","X-rays","ultraviolet","visible light"],a:0,lec:'Sep 16 lecture: the EM spectrum',e:"Radio sits at the low-energy end: <strong>lowest E, lowest frequency, longest wavelength</strong>. Gamma rays are the opposite end."},
{chId:'light',ch:'Light and the EM Spectrum',q:"As the frequency of light increases, its wavelength ____ and its photon energy ____.",o:["decreases; increases","increases; increases","decreases; decreases","increases; decreases","stays the same; increases"],a:0,lec:'Sep 16 lecture: the EM spectrum',e:"<div class='math-block'>c = &lambda;&nu; &rarr; &lambda; and &nu; are inversely related<br>E = h&nu; &rarr; E and &nu; rise together</div>So high frequency means <strong>short wavelength and high energy</strong>."},
{chId:'light',ch:'Light and the EM Spectrum',q:"How fast do radio waves and gamma rays travel through a vacuum, compared with each other?",o:["both at 3.00 &times; 10<sup>8</sup> m/s","gamma rays are faster because they carry more energy","radio waves are faster because their wavelength is longer","both at 340 m/s","it depends on the amplitude of each wave"],a:0,lec:'Sep 14 lecture: nature of light',e:"<strong>All electromagnetic waves move at the same constant speed in a vacuum, c = 3.00 &times; 10<sup>8</sup> m/s.</strong> Energy changes frequency and wavelength, never the speed. 340 m/s is the speed of sound; light is about 10<sup>6</sup> times faster."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Two light waves have the same wavelength but different amplitudes. What is different about them?",o:["brightness","color","frequency","energy per photon","speed in a vacuum"],a:0,lec:'Sep 16 lecture: characteristics of a wave',e:"From his wave slides: <strong>different amplitudes = different brightness</strong>, <strong>different wavelengths = different colors</strong>. Same wavelength means same frequency, same color and same energy per photon."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Handout 7 #1. Find the wavelength (in nm) and the color of light with a frequency of 4.29 &times; 10<sup>14</sup> Hz.",o:["699 nm, red","699 nm, violet","1.43 nm, X-ray","429 nm, blue","6.99 &times; 10<sup>-7</sup> nm, red"],a:0,lec:'Handout 7 and the Sep 16 lecture',e:"<div class='math-block'>Know: &nu; = 4.29 &times; 10<sup>14</sup> Hz (s<sup>-1</sup>), c = 3.00 &times; 10<sup>8</sup> m/s &nbsp; Want: &lambda; in nm<br>&lambda; = c/&nu; = (3.00 &times; 10<sup>8</sup> m/s)/(4.29 &times; 10<sup>14</sup> s<sup>-1</sup>) = 6.99 &times; 10<sup>-7</sup> m<br>6.99 &times; 10<sup>-7</sup> m &times; (10<sup>9</sup> nm / 1 m) = <strong>699 nm</strong></div>Visible light runs 400 (violet) to 750 nm (red), so 699 nm is <strong>red</strong>. '6.99 &times; 10<sup>-7</sup> nm, red' forgot to convert out of meters."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Handout 7 #2. What is the energy (in J) of a photon whose wavelength is 400. nm?",o:["4.97 &times; 10<sup>-19</sup> J","4.97 &times; 10<sup>-28</sup> J","2.65 &times; 10<sup>-40</sup> J","1.99 &times; 10<sup>-25</sup> J","7.50 &times; 10<sup>14</sup> J"],a:0,lec:'Handout 7 and the Sep 16 lecture',e:"<div class='math-block'>E = hc/&lambda;<br>&lambda; = 400. nm &times; (1 m / 10<sup>9</sup> nm) = 4.00 &times; 10<sup>-7</sup> m<br>E = (6.626 &times; 10<sup>-34</sup> J&middot;s)(3.00 &times; 10<sup>8</sup> m/s) / (4.00 &times; 10<sup>-7</sup> m)<br>= <strong>4.97 &times; 10<sup>-19</sup> J</strong> (3 SF)</div>Leaving &lambda; in nm gives the 10<sup>-28</sup> trap. 1.99 &times; 10<sup>-25</sup> is just hc with no division. Two of these photons would be 9.94 &times; 10<sup>-19</sup> J."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Chapter 3 Worksheet #1. A photon has a wavelength of 235 nm. What is its frequency (in Hz)?",o:["1.28 &times; 10<sup>15</sup> Hz","1.28 &times; 10<sup>6</sup> Hz","7.05 &times; 10<sup>10</sup> Hz","7.83 &times; 10<sup>-16</sup> Hz","8.46 &times; 10<sup>-19</sup> Hz"],a:0,lec:'Chapter 3 Review Worksheet',e:"<div class='math-block'>&nu; = c/&lambda; = (3.00 &times; 10<sup>8</sup> m/s) / (235 nm &times; 1 m/10<sup>9</sup> nm)<br>= (3.00 &times; 10<sup>8</sup>)/(2.35 &times; 10<sup>-7</sup>) = <strong>1.28 &times; 10<sup>15</sup> Hz</strong></div>1.28 &times; 10<sup>6</sup> is what you get without converting nm to m. 8.46 &times; 10<sup>-19</sup> is the photon's energy in J, which is worksheet #2."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Chapter 3 Worksheet #2. What is the energy (in J) of a photon with a wavelength of 235 nm?",o:["8.46 &times; 10<sup>-19</sup> J","8.46 &times; 10<sup>-28</sup> J","1.28 &times; 10<sup>15</sup> J","4.67 &times; 10<sup>-41</sup> J","1.56 &times; 10<sup>-31</sup> J"],a:0,lec:'Chapter 3 Review Worksheet',e:"<div class='math-block'>E = hc/&lambda; = (6.626 &times; 10<sup>-34</sup> J&middot;s)(3.00 &times; 10<sup>8</sup> m/s) / (2.35 &times; 10<sup>-7</sup> m)<br>= <strong>8.46 &times; 10<sup>-19</sup> J</strong></div>Shorter wavelength than the 400. nm photon (4.97 &times; 10<sup>-19</sup> J), so more energy. That check alone kills most wrong answers."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Chapter 3 Worksheet #3. What is the TOTAL energy (in J) of 2 photons if each has a wavelength of 1032 &micro;m?",o:["3.85 &times; 10<sup>-22</sup> J","1.93 &times; 10<sup>-22</sup> J","3.85 &times; 10<sup>-16</sup> J","9.63 &times; 10<sup>-23</sup> J","3.85 &times; 10<sup>-25</sup> J"],a:0,lec:'Chapter 3 Review Worksheet',e:"<div class='math-block'>&lambda; = 1032 &micro;m &times; (1 m / 10<sup>6</sup> &micro;m) = 1.032 &times; 10<sup>-3</sup> m<br>E<sub>1 photon</sub> = hc/&lambda; = 1.93 &times; 10<sup>-22</sup> J<br>2 photons &times; (1.926 &times; 10<sup>-22</sup> J / 1 photon) = <strong>3.85 &times; 10<sup>-22</sup> J</strong> (carry the unrounded value; 2 &times; 1.93 would give 3.86)</div>The trap is stopping at one photon (1.93 &times; 10<sup>-22</sup> J). Energy scales with the number of photons."},
{chId:'light',ch:'Light and the EM Spectrum',q:"An FM station broadcasts at 94.7 MHz. What is the wavelength of these radio waves?",o:["3.17 m","3.17 &times; 10<sup>6</sup> m","3.17 &times; 10<sup>-6</sup> m","0.316 m","2.84 &times; 10<sup>16</sup> m"],a:0,lec:'Sep 16 lecture: c = &lambda;&nu;',e:"<div class='math-block'>&nu; = 94.7 MHz &times; (10<sup>6</sup> Hz / 1 MHz) = 9.47 &times; 10<sup>7</sup> s<sup>-1</sup><br>&lambda; = c/&nu; = (3.00 &times; 10<sup>8</sup> m/s)/(9.47 &times; 10<sup>7</sup> s<sup>-1</sup>) = <strong>3.17 m</strong></div>Convert MHz to Hz first, the same move as worksheet #4. A wavelength of meters fits radio, the longest-wavelength region."},
{chId:'light',ch:'Light and the EM Spectrum',q:"What is the energy of a photon with a frequency of 5.00 &times; 10<sup>14</sup> Hz?",o:["3.31 &times; 10<sup>-19</sup> J","1.33 &times; 10<sup>-48</sup> J","7.55 &times; 10<sup>47</sup> J","6.00 &times; 10<sup>-7</sup> J","1.99 &times; 10<sup>-25</sup> J"],a:0,lec:'Sep 16 lecture: E = h&nu;',e:"<div class='math-block'>E = h&nu; = (6.626 &times; 10<sup>-34</sup> J&middot;s)(5.00 &times; 10<sup>14</sup> s<sup>-1</sup>) = <strong>3.31 &times; 10<sup>-19</sup> J</strong></div>Given frequency, use E = h&nu; directly. You only need c when you start from a wavelength."},
{chId:'light',ch:'Light and the EM Spectrum',q:"A photon carries 3.98 &times; 10<sup>-19</sup> J. What is its wavelength in nm?",o:["499 nm","4.99 &times; 10<sup>-7</sup> nm","2.00 &times; 10<sup>3</sup> nm","6.01 &times; 10<sup>14</sup> nm","166 nm"],a:0,lec:'Sep 16 lecture: E = hc/&lambda;',e:"<div class='math-block'>&lambda; = hc/E = (6.626 &times; 10<sup>-34</sup>)(3.00 &times; 10<sup>8</sup>) / (3.98 &times; 10<sup>-19</sup>)<br>= 4.99 &times; 10<sup>-7</sup> m &times; (10<sup>9</sup> nm/1 m) = <strong>499 nm</strong></div>Rearranging E = hc/&lambda; for &lambda; is fair game in Part C. 4.99 &times; 10<sup>-7</sup> is the right number in meters, mislabeled as nm."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Which color of visible light has the HIGHEST energy per photon?",o:["violet","red","green","yellow","orange"],a:0,lec:'Sep 16 lecture: color and visible light',e:"Visible light runs from red (about 750 nm, 2.65 &times; 10<sup>-19</sup> J/photon) to violet (400 nm, 4.97 &times; 10<sup>-19</sup> J/photon). <strong>Shortest wavelength = highest energy = violet</strong>. ROYGBV goes from low to high energy."},
{chId:'light',ch:'Light and the EM Spectrum',q:"A shirt looks green under white light. What is happening to the light?",o:["green is reflected; the complementary colors are absorbed by electrons in the dye","green is absorbed; every other color is reflected","all colors are absorbed and green is emitted as heat","all colors are reflected equally","green light travels faster than the other colors"],a:0,lec:'Sep 16 lecture: color and visible light',e:"His slide: <strong>observed color = reflected or transmitted color</strong>; the rest is <strong>absorbed</strong>, and observed and absorbed colors are <strong>complementary</strong>. The absorbed energy goes to the electrons in the atoms, ions or molecules."},
{chId:'light',ch:'Light and the EM Spectrum',q:"Which type of radiation causes the bonds in a molecule to VIBRATE?",o:["infrared","microwave","radio","X-ray","gamma"],a:0,lec:'Sep 14 lecture: effect of EM radiation on matter',e:"His list: <strong>X-ray</strong> locates electron clouds; <strong>UV and visible</strong> excite electrons; <strong>IR makes bonds vibrate</strong>; <strong>microwaves make bonds and molecules rotate</strong>; <strong>radio</strong> excites nuclei (NMR)."},
{chId:'light',ch:'Light and the EM Spectrum',q:"How much energy is carried by 1 mole of photons with a wavelength of 400. nm?",o:["299 kJ","4.97 &times; 10<sup>-22</sup> kJ","8.25 &times; 10<sup>-43</sup> kJ","2.99 &times; 10<sup>8</sup> kJ","4.97 &times; 10<sup>-19</sup> kJ"],a:0,lec:'Handout 7 and the mole (Ch 6.1)',e:"<div class='math-block'>E per photon = 4.97 &times; 10<sup>-19</sup> J (Handout 7 #2)<br>&times; 6.022 &times; 10<sup>23</sup> photons/mol = 2.99 &times; 10<sup>5</sup> J<br>&times; (1 kJ / 1000 J) = <strong>299 kJ</strong></div>Same particles &harr; mol move as Exam 1; a photon is just another particle. His slide sets this next to a C-C bond (350 kJ/mol): 299 kJ per mole of photons is less, so 400 nm light cannot break C-C bonds. UV below about 342 nm can."},

// ===== 2. Emission spectra, Bohr and Rydberg =====
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"Handout 7 #3. What is the wavelength (in nm) of the photon emitted when an electron in hydrogen drops from the 3rd shell to the 1st?",o:["103 nm","656 nm","9.75 &times; 10<sup>6</sup> nm","1.03 &times; 10<sup>-7</sup> nm","122 nm"],a:0,lec:'Handout 7 and the Sep 18 lecture: Rydberg',e:"<div class='math-block'>n<sub>i</sub> = 3, n<sub>f</sub> = 1, R<sub>H</sub> = 1.097 &times; 10<sup>7</sup> m<sup>-1</sup><br>1/&lambda; = R<sub>H</sub>(1/n<sub>f</sub><sup>2</sup> - 1/n<sub>i</sub><sup>2</sup>) = 1.097 &times; 10<sup>7</sup>(1/1 - 1/9) = 9.75 &times; 10<sup>6</sup> m<sup>-1</sup><br>&lambda; = 1/(9.75 &times; 10<sup>6</sup>) = 1.03 &times; 10<sup>-7</sup> m = <strong>103 nm</strong></div>Positive answer, so energy left the atom as a photon. 103 nm is ultraviolet. Do not forget the final 1/x: 9.75 &times; 10<sup>6</sup> is 1/&lambda;, not &lambda;. 122 nm is the 2 &rarr; 1 line."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"Handout 7 #4 (his Sep 21 bonus). An atom emits light at 6.16 &times; 10<sup>14</sup> Hz. The electron relaxed to the 2nd shell. Which shell did it start in?",o:["n = 4","n = 3","n = 5","n = 6","n = 16"],a:0,lec:'Handout 7 and the Sep 21 lecture',e:"<div class='math-block'>&nu; = R<sub>H</sub>(1/n<sub>f</sub><sup>2</sup> - 1/n<sub>i</sub><sup>2</sup>), R<sub>H</sub> = 3.290 &times; 10<sup>15</sup> s<sup>-1</sup>, n<sub>f</sub> = 2<br>&nu;/R<sub>H</sub> = 0.1872 = 1/4 - 1/n<sub>i</sub><sup>2</sup><br>1/n<sub>i</sub><sup>2</sup> = 0.2500 - 0.1872 = 0.0628 &rarr; n<sub>i</sub><sup>2</sup> = 15.9 &rarr; n<sub>i</sub> = 3.99</div>His slide: the calculator gives 3.992, so <strong>n<sub>i</sub> = 4</strong>. Shells are whole numbers, so round. 16 is n<sub>i</sub><sup>2</sup>, the step before the square root."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"Chapter 3 Worksheet #4. An electron starts in the 5th shell. The photon that leaves has a frequency of 2.34 &times; 10<sup>8</sup> MHz. Which shell did the electron end in?",o:["n = 3","n = 2","n = 4","n = 1","n = 9"],a:0,lec:'Chapter 3 Review Worksheet',e:"<div class='math-block'>2.34 &times; 10<sup>8</sup> MHz &times; (10<sup>6</sup> Hz/1 MHz) = 2.34 &times; 10<sup>14</sup> Hz (match the constant's units)<br>1/n<sub>f</sub><sup>2</sup> = &nu;/R<sub>H</sub> + 1/n<sub>i</sub><sup>2</sup> = 0.0711 + 0.0400 = 0.1111<br>n<sub>f</sub> = &radic;(1/0.1111) = 2.9998 &rarr; <strong>n<sub>f</sub> = 3</strong></div>The key's two traps: convert MHz to Hz before dividing by R<sub>H</sub>, and invert before the square root. 9 is n<sub>f</sub><sup>2</sup>."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"Using his sign convention for the Rydberg equation, what does a NEGATIVE answer mean?",o:["energy was absorbed by the atom as a photon","energy was emitted by the atom as a photon","the electron left the atom","the calculation used the wrong constant","the photon has negative wavelength"],a:0,lec:'Sep 18 lecture: meaning of signs',e:"His slide (E<sub>photon</sub> = -E<sub>atom</sub>): <strong>positive answer &rarr; energy emitted from the atom as a photon</strong>; <strong>negative answer &rarr; energy absorbed by the atom</strong>. With 1/n<sub>f</sub><sup>2</sup> - 1/n<sub>i</sub><sup>2</sup>, an electron moving UP (n<sub>f</sub> &gt; n<sub>i</sub>) gives a negative number. Report wavelength as a positive length. Heads-up: OpenStax and Knewton often report &Delta;E of the ATOM, which is negative for emission. Same physics, opposite sign; on his exam use his rule."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"An electron in hydrogen drops from n = 3 to n = 2. What is the wavelength of the emitted light?",o:["656 nm (red)","103 nm (ultraviolet)","486 nm (blue-green)","1.52 &times; 10<sup>6</sup> nm","434 nm (violet)"],a:0,lec:'Sep 18 lecture: Rydberg',e:"<div class='math-block'>1/&lambda; = 1.097 &times; 10<sup>7</sup>(1/2<sup>2</sup> - 1/3<sup>2</sup>) = 1.097 &times; 10<sup>7</sup>(0.25000 - 0.11111) = 1.524 &times; 10<sup>6</sup> m<sup>-1</sup><br>&lambda; = 6.56 &times; 10<sup>-7</sup> m = <strong>656 nm</strong></div>This is hydrogen's red line. 486 nm is the 4 &rarr; 2 line and 434 nm is 5 &rarr; 2."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"Which electron transition in a hydrogen atom EMITS the most energy?",o:["n = 2 &rarr; n = 1","n = 3 &rarr; n = 2","n = 4 &rarr; n = 2","n = 5 &rarr; n = 3","n = 1 &rarr; n = 3"],a:0,lec:'Sep 21 lecture: transitions in hydrogen',e:"Energy levels crowd together as n rises, so the <strong>biggest gap is between n = 2 and n = 1</strong>. Compare the brackets: (1/1 - 1/4) = 0.75 beats (1/4 - 1/9) = 0.14, (1/4 - 1/16) = 0.19 and (1/9 - 1/25) = 0.07. The 1 &rarr; 3 jump is an absorption, so it emits nothing."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"What is the energy of the photon emitted when an electron in hydrogen relaxes from n = 2 to n = 1?",o:["1.64 &times; 10<sup>-18</sup> J","2.18 &times; 10<sup>-18</sup> J","5.45 &times; 10<sup>-19</sup> J","-1.64 &times; 10<sup>-18</sup> J, because energy is lost","1.22 &times; 10<sup>-7</sup> J"],a:0,lec:'Sep 18 lecture: Rydberg, energy form',e:"<div class='math-block'>&Delta;E = R<sub>H</sub>(1/n<sub>f</sub><sup>2</sup> - 1/n<sub>i</sub><sup>2</sup>), R<sub>H</sub> = 2.18 &times; 10<sup>-18</sup> J<br>= 2.18 &times; 10<sup>-18</sup>(1/1 - 1/4) = <strong>1.64 &times; 10<sup>-18</sup> J</strong></div>Positive in his convention means emitted. Use the R<sub>H</sub> that matches what you want: J for energy, m<sup>-1</sup> for 1/&lambda;, s<sup>-1</sup> for frequency."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"A question gives you a FREQUENCY and asks for a shell number. Which form of the Rydberg constant do you use?",o:["3.290 &times; 10<sup>15</sup> s<sup>-1</sup>","1.097 &times; 10<sup>7</sup> m<sup>-1</sup>","2.18 &times; 10<sup>-18</sup> J","6.626 &times; 10<sup>-34</sup> J&middot;s","3.00 &times; 10<sup>8</sup> m/s"],a:0,lec:'Sep 18 lecture: three Rydberg equations',e:"The formula sheet gives three versions. Pick the constant whose units match the quantity: <strong>frequency (s<sup>-1</sup>) &rarr; 3.290 &times; 10<sup>15</sup> s<sup>-1</sup></strong>, 1/wavelength &rarr; 1.097 &times; 10<sup>7</sup> m<sup>-1</sup>, energy &rarr; 2.18 &times; 10<sup>-18</sup> J. Convert MHz or nm into s<sup>-1</sup> or m first."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"What is an emission spectrum?",o:["a plot of the exact energies of light leaving a species after it has been excited","a continuous rainbow of every visible color","the energy needed to remove an electron from an atom","the range of wavelengths a substance absorbs at room temperature","a diagram of orbital filling order"],a:0,lec:'Sep 14 lecture: emission spectrum',e:"His definition: <strong>a plot detailing the exact energies of light leaving a species after excitation</strong>. It shows separate lines, not a rainbow, because the electron's energy levels are quantized."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"In a flame test, sodium glows yellow-orange and potassium glows violet. Why does each element give its own color?",o:["each element has its own set of allowed energy levels, so its electrons emit only specific energies","each element burns at a different temperature","the flame reflects the color of the solid","heavier atoms always emit longer wavelengths","the color comes from the nucleus breaking apart"],a:0,lec:'Sep 16 lecture: flame test',e:"His slide: <strong>the emitted color is unique to the atom, like a fingerprint</strong>, and a specific color is emitted, not white light. Electrons absorb energy, jump up, then drop back down between that element's own quantized levels."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"Which statement describes the Bohr model of the hydrogen atom?",o:["the electron can occupy only certain orbits, and the energy of each orbit is quantized","the electron can have any energy as it spirals into the nucleus","the electron's exact position and speed are known at every moment","electrons fill orbitals according to Hund's rule","the atom is a sphere of positive charge with electrons embedded in it"],a:0,lec:'Sep 14 and 18 lectures: Bohr model',e:"<strong>Energy of each orbit is quantized; the electron is only allowed in certain volumes around the nucleus</strong>, and energy increases outward. 'A sphere of positive charge with electrons embedded in it' is Thomson's plum pudding model."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"An electron moves from n = 2 up to n = 4. Which describes this?",o:["excitation: energy is absorbed and n increases","emission: energy is released and n increases","emission: energy is released and n decreases","excitation: energy is released and n decreases","ionization: the electron leaves the atom"],a:0,lec:'Sep 21 lecture: transitions',e:"His slide: <strong>excitation = energy absorbed and n increases (n<sub>f</sub> &gt; n<sub>i</sub>)</strong>; <strong>emission = energy released and n decreases (n<sub>f</sub> &lt; n<sub>i</sub>)</strong>."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"As n increases, what happens to the energy gap between neighboring energy levels?",o:["it gets smaller","it gets larger","it stays the same","it becomes negative","it doubles each time"],a:0,lec:'Sep 25 lecture: ordering of orbitals',e:"His orbital-energy slide: <strong>the energy difference between levels becomes smaller for higher energy levels</strong>. That crowding is also why 4s and 3d end up close enough to swap order, and why Cr and Cu are exceptions."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"An electron in hydrogen drops from n = 4 to n = 2. What is the frequency of the emitted photon?",o:["6.17 &times; 10<sup>14</sup> Hz","3.08 &times; 10<sup>15</sup> Hz","2.06 &times; 10<sup>6</sup> Hz","4.57 &times; 10<sup>14</sup> Hz","1.62 &times; 10<sup>-15</sup> Hz"],a:0,lec:'Sep 18 lecture: Rydberg, frequency form',e:"<div class='math-block'>&nu; = R<sub>H</sub>(1/n<sub>f</sub><sup>2</sup> - 1/n<sub>i</sub><sup>2</sup>) = 3.290 &times; 10<sup>15</sup>(1/4 - 1/16)<br>= 3.290 &times; 10<sup>15</sup> &times; 0.1875 = <strong>6.17 &times; 10<sup>14</sup> Hz</strong></div>Note this is almost exactly Handout 7 #4's frequency (6.16 &times; 10<sup>14</sup>) run backwards. 4.57 &times; 10<sup>14</sup> is the 3 &rarr; 2 line."},

// ===== 3. Wave-particle duality =====
{chId:'qm',ch:'Wave-Particle Duality',q:"In the double-slit experiment, electrons produced an interference pattern. What did that show?",o:["electrons have both particle and wave properties","electrons are only particles","electrons have no mass","light is only a particle","electrons travel faster than light"],a:0,lec:'Sep 18 lecture: double slit',e:"Particles should make two bands. The electrons <strong>gave results like a wave</strong> instead, so the electron <strong>has particle and wave properties</strong>. That is the dual nature the study guide asks about."},
{chId:'qm',ch:'Wave-Particle Duality',q:"The de Broglie relation is &lambda; = h/mv. What does it say?",o:["all matter has a wavelength, linked to its momentum","only photons have a wavelength","an object's wavelength grows as it speeds up","mass and wavelength are directly proportional","the electron's position can be known exactly"],a:0,lec:'Sep 18 lecture: de Broglie',e:"De Broglie (Nobel 1929) tied wave nature (&lambda;) to particle nature (mv = momentum). <strong>All matter has a wavelength.</strong> Larger mass or larger speed means a SMALLER wavelength. Note: this equation is NOT on the formula sheet."},
{chId:'qm',ch:'Wave-Particle Duality',q:"A baseball (0.145 kg) at 24.6 m/s has a de Broglie wavelength of about 1.9 &times; 10<sup>-34</sup> m. Why do we never notice a baseball's wave behavior?",o:["its mass is so large that the wavelength is far too small to detect","baseballs are not made of matter waves","the wavelength is too long to fit on Earth","only charged objects have wavelengths","it moves too slowly to have a wavelength"],a:0,lec:'Sep 18 lecture: de Broglie',e:"<div class='math-block'>&lambda; = h/mv = 6.626 &times; 10<sup>-34</sup> / (0.145 &times; 24.6) = 1.86 &times; 10<sup>-34</sup> m</div>Far smaller than an atom. Wave behavior only shows up for tiny masses like the electron, whose wavelength is about the size of an atom."},
{chId:'qm',ch:'Wave-Particle Duality',q:"Find the de Broglie wavelength of an electron (m = 9.11 &times; 10<sup>-31</sup> kg) moving at 2.65 &times; 10<sup>6</sup> m/s.",o:["2.74 &times; 10<sup>-10</sup> m","3.64 &times; 10<sup>9</sup> m","1.60 &times; 10<sup>-39</sup> m","2.41 &times; 10<sup>-24</sup> m","2.74 &times; 10<sup>-1</sup> m"],a:0,lec:'Sep 18 lecture: de Broglie',e:"<div class='math-block'>&lambda; = h/(mv) = 6.626 &times; 10<sup>-34</sup> J&middot;s / (9.11 &times; 10<sup>-31</sup> kg &times; 2.65 &times; 10<sup>6</sup> m/s)<br>= 6.626 &times; 10<sup>-34</sup> / 2.41 &times; 10<sup>-24</sup> = <strong>2.74 &times; 10<sup>-10</sup> m</strong> (0.274 nm)</div>About the size of an atom, which is why electrons diffract. 2.41 &times; 10<sup>-24</sup> is the momentum, not the wavelength."},
{chId:'qm',ch:'Wave-Particle Duality',q:"What does the Heisenberg uncertainty principle say?",o:["a particle's position and velocity cannot both be known precisely at the same time","an electron's energy can never be known","electrons orbit the nucleus in fixed circles","no two electrons can have the same four quantum numbers","electrons fill the lowest energy orbitals first"],a:0,lec:'Sep 18 lecture: Heisenberg',e:"<strong>Position and velocity cannot be known well simultaneously.</strong> His consequence: if we know the electron's energy, then its position must be given as a <strong>probability</strong>. That is why orbitals are probability regions, not paths. 'No two electrons can have the same four quantum numbers' is Pauli; 'lowest energy orbitals first' is aufbau."},
{chId:'qm',ch:'Wave-Particle Duality',q:"In Schr&ouml;dinger's equation, what does &psi;<sup>2</sup> (the wavefunction squared) represent?",o:["the probability of finding the electron, which defines an orbital","the electron's exact path","the energy of the photon","the speed of the electron","nothing physical at all"],a:0,lec:'Sep 18 lecture: Schr&ouml;dinger',e:"His slide: <strong>&psi; itself is physically meaningless; &psi;<sup>2</sup> is the probability of finding the electron (the orbital)</strong>. 'Nothing physical at all' describes &psi;, not &psi;<sup>2</sup>."},
{chId:'qm',ch:'Wave-Particle Duality',q:"An orbital surface plot is drawn to enclose the region where the electron is found what fraction of the time?",o:["90%","100%","50%","10%","99.9%"],a:0,lec:'Sep 18 lecture: the 1s orbital',e:"<strong>A 3D shape where the electron is found 90% of the time</strong>. It can never be 100%, because the probability only fades with distance, it never hits zero."},
{chId:'qm',ch:'Wave-Particle Duality',q:"If an electron speeds up, what happens to its de Broglie wavelength?",o:["it decreases","it increases","it stays the same","it becomes zero","it becomes negative"],a:0,lec:'Sep 18 lecture: de Broglie',e:"&lambda; = h/(mv): v is in the denominator, so <strong>faster means shorter wavelength</strong>."},

// ===== 4. Quantum numbers and orbitals =====
{chId:'qn',ch:'Quantum Numbers',q:"What does the principal quantum number, n, describe?",o:["the size and energy of the orbital (the shell)","the shape of the orbital","the orientation of the orbital","the spin of the electron","the number of electrons in the atom"],a:0,lec:'Handout 8: quantum numbers',e:"<strong>n = shell: size and energy.</strong> As n goes up, the orbital gets bigger and higher in energy. In his mailing-address analogy, n is the <strong>city</strong>."},
{chId:'qn',ch:'Quantum Numbers',q:"What does the angular momentum quantum number, &#8467;, describe?",o:["the shape of the orbital (the subshell)","the size of the orbital","the orientation of the orbital in space","the spin of the electron","the number of shells"],a:0,lec:'Handout 8: quantum numbers',e:"<strong>&#8467; = subshell: shape</strong> (0 = s, 1 = p, 2 = d, 3 = f). It slightly affects energy too: s &lt; p &lt; d &lt; f. In the analogy it is the <strong>street</strong>."},
{chId:'qn',ch:'Quantum Numbers',q:"What does the magnetic quantum number, m<sub>&#8467;</sub>, describe?",o:["the orientation of an orbital, and so the number of orbitals in a subshell","the shape of the orbital","the size of the orbital","the spin of the electron","the energy of the shell"],a:0,lec:'Handout 8: quantum numbers',e:"<strong>m<sub>&#8467;</sub> = orientation</strong>, running from -&#8467; to +&#8467;. The count of allowed values (2&#8467; + 1) is the <strong>number of orbitals in the subshell</strong>. In the analogy it is the <strong>house number</strong>."},
{chId:'qn',ch:'Quantum Numbers',q:"What are the allowed values of the spin quantum number, m<sub>s</sub>?",o:["+&frac12; and -&frac12;","0 and 1","-1, 0 and +1","any value from 0 to n - 1","+1 and -1"],a:0,lec:'Handout 8: quantum numbers',e:"<strong>m<sub>s</sub> = +&frac12; for a spin-up electron, -&frac12; for spin-down.</strong> Only two values, which is why one orbital holds at most 2 electrons."},
{chId:'qn',ch:'Quantum Numbers',q:"For n = 3, what values can &#8467; take?",o:["0, 1, 2","1, 2, 3","0, 1, 2, 3","-2, -1, 0, 1, 2","3 only"],a:0,lec:'Handout 8: quantum numbers',e:"<strong>&#8467; runs from 0 to n - 1</strong>, so n = 3 allows 0, 1 and 2: the 3s, 3p and 3d subshells. &#8467; can never equal n."},
{chId:'qn',ch:'Quantum Numbers',q:"Handout 8 #3. Does the orbital (n, &#8467;, m<sub>&#8467;</sub>) = (1, 1, 0) exist?",o:["No. &#8467; cannot equal n, so there is no 1p subshell","Yes, it is a 1p orbital","Yes, it is a 1s orbital","Yes, it is a 2p orbital","No, because m<sub>&#8467;</sub> cannot be 0"],a:0,lec:'Handout 8: quantum numbers',e:"His hint: <strong>read left to right and check each number against the one before it</strong>. n = 1 allows only &#8467; = 0, so &#8467; = 1 fails. It would be a 1p orbital, and there is no 1p subshell."},
{chId:'qn',ch:'Quantum Numbers',q:"Handout 8 #4. Name the orbital (4, 3, -3), or say it does not exist.",o:["4f","4d","3f","DNE, because m<sub>&#8467;</sub> cannot be negative","DNE, because &#8467; cannot be 3"],a:0,lec:'Handout 8: quantum numbers',e:"n = 4 allows &#8467; = 0 to 3, so &#8467; = 3 (f) is fine. &#8467; = 3 allows m<sub>&#8467;</sub> = -3 to +3, so -3 is fine. <strong>It is a 4f orbital.</strong>"},
{chId:'qn',ch:'Quantum Numbers',q:"Handout 8 #5. Does the orbital (4, 3, 5) exist?",o:["No. m<sub>&#8467;</sub> must lie between -3 and +3","Yes, it is a 4f orbital","Yes, it is a 4d orbital","No, because &#8467; cannot be 3 when n = 4","Yes, it is a 5f orbital"],a:0,lec:'Handout 8: quantum numbers',e:"n and &#8467; are fine (it looks like a 4f), but <strong>m<sub>&#8467;</sub> must be between -&#8467; and +&#8467;</strong>, here -3 to +3. 5 is out of range, so DNE."},
{chId:'qn',ch:'Quantum Numbers',q:"Handout 8 #6. Name the orbital (5, 2, 1).",o:["5d","5p","2d","5f","DNE"],a:0,lec:'Handout 8: quantum numbers',e:"n = 5 allows &#8467; up to 4; &#8467; = 2 is a d subshell; m<sub>&#8467;</sub> = 1 is within -2 to +2. <strong>5d orbital.</strong>"},
{chId:'qn',ch:'Quantum Numbers',q:"Handout 9 #4 and #5. Which orbital is n = 3, &#8467; = 2, m<sub>&#8467;</sub> = 2, and what is its most likely shape?",o:["a 3d orbital, cloverleaf","a 3p orbital, dumbbell","a 2d orbital, cloverleaf","a 3d orbital, sphere","a 3f orbital, cloverleaf"],a:0,lec:'Handout 9: quantum numbers',e:"&#8467; = 2 is d, so it is <strong>one of the five 3d orbitals</strong>. His answer for the shape: <strong>cloverleaf</strong>, because four of the five d orbitals are cloverleaves and one looks like a p orbital with a ring."},
{chId:'qn',ch:'Quantum Numbers',q:"Handout 9 #3. How many orbitals are in the 4th shell?",o:["16","4","32","9","10"],a:0,lec:'Handout 9: quantum numbers',e:"<div class='math-block'>4s (1) + 4p (3) + 4d (5) + 4f (7) = 16 orbitals</div>Shortcut: <strong>n<sup>2</sup> orbitals per shell</strong>. 32 is the number of ELECTRONS the 4th shell can hold (2n<sup>2</sup>)."},
{chId:'qn',ch:'Quantum Numbers',q:"What is the maximum number of electrons the n = 3 shell can hold?",o:["18","8","9","32","6"],a:0,lec:'Sep 21 lecture: shell model',e:"His shell model: 2, 8, 18, 32 electrons for n = 1 to 4. <strong>n = 3 has 9 orbitals (3s, 3p, 3d) &times; 2 electrons = 18.</strong> 8 is a common trap, because the third ROW of the table has only 8 elements."},
{chId:'qn',ch:'Quantum Numbers',q:"How many orbitals make up a d subshell, and how many electrons can it hold?",o:["5 orbitals, 10 electrons","3 orbitals, 6 electrons","7 orbitals, 14 electrons","5 orbitals, 5 electrons","10 orbitals, 10 electrons"],a:0,lec:'Sep 25 lecture: linking orbitals to the table',e:"s: 1 orbital, 2 e<sup>-</sup>. p: 3, 6. <strong>d: 5, 10.</strong> f: 7, 14. Those electron counts are the widths of the s, p, d and f blocks of the periodic table."},
{chId:'qn',ch:'Quantum Numbers',q:"Which orbital does NOT exist?",o:["2d","2p","3d","4f","1s"],a:0,lec:'Handout 8: quantum numbers',e:"A d subshell needs &#8467; = 2, and &#8467; can be at most n - 1. n = 2 allows only &#8467; = 0 and 1 (2s, 2p). <strong>There is no 2d.</strong> The same rule kills 1p and 3f."},
{chId:'qn',ch:'Quantum Numbers',q:"Which set of four quantum numbers (n, &#8467;, m<sub>&#8467;</sub>, m<sub>s</sub>) is NOT allowed?",o:["(3, 0, 0, 0)","(3, 1, 0, +&frac12;)","(2, 1, -1, -&frac12;)","(4, 3, 2, +&frac12;)","(1, 0, 0, -&frac12;)"],a:0,lec:'Handout 8: quantum numbers',e:"The first three numbers are fine (a 3s orbital), but <strong>m<sub>s</sub> can only be +&frac12; or -&frac12;</strong>, never 0."},
{chId:'qn',ch:'Quantum Numbers',q:"Describe the p orbitals.",o:["dumbbell-shaped, three per subshell at right angles to each other, found from n = 2 up","spherical, one per subshell, found in every shell","cloverleaf-shaped, five per subshell, found from n = 3 up","dumbbell-shaped, one per subshell, found only in n = 2","spherical, three per subshell, found from n = 1 up"],a:0,lec:'Sep 21 lecture: surface plots of the 2p orbitals',e:"His slides: p orbitals are <strong>dumbbells</strong>, there are <strong>3</strong> (m<sub>&#8467;</sub> = -1, 0, +1), they are <strong>orthogonal</strong> (along x, y, z), each has <strong>one nodal plane</strong>, and they exist when <strong>n &ge; 2</strong>. The s orbital is the single sphere found in every shell."},
{chId:'qn',ch:'Quantum Numbers',q:"In his mailing-address analogy, which quantum number is the 'street'?",o:["&#8467;, the subshell","n, the shell","m<sub>&#8467;</sub>, the orbital","m<sub>s</sub>, the spin","Z, the atomic number"],a:0,lec:'Handout 8: quantum numbers',e:"<strong>n = city</strong> (shell), <strong>&#8467; = street</strong> (subshell), <strong>m<sub>&#8467;</sub> = house number</strong> (one orbital). An atomic orbital is the 'house' where the electron lives."},
{chId:'qn',ch:'Quantum Numbers',q:"Chapter 3 Worksheet #8c. Can the orbital (4, 2, -3) exist?",o:["No. With &#8467; = 2, m<sub>&#8467;</sub> can only be -2 to +2","Yes, it is a 4d orbital","Yes, it is a 4f orbital","No, because &#8467; cannot be 2 when n = 4","Yes, it is a 3d orbital"],a:0,lec:'Chapter 3 Review Worksheet',e:"n = 4 allows &#8467; = 0 to 3, so &#8467; = 2 is fine. But &#8467; = 2 allows m<sub>&#8467;</sub> = -2, -1, 0, +1, +2, so <strong>-3 is not possible</strong>."},
{chId:'qn',ch:'Quantum Numbers',q:"Handout 9 #6. Do these orbitals exist: (4, 1, -1) and (5, 1, -2)?",o:["(4, 1, -1) is a 4p orbital; (5, 1, -2) does not exist","both exist","neither exists","(4, 1, -1) does not exist; (5, 1, -2) is a 5p orbital","(4, 1, -1) is a 4s orbital; (5, 1, -2) is a 5d orbital"],a:0,lec:'Handout 9: quantum numbers',e:"His answers: <strong>(4, 1, -1) yes, a 4p orbital</strong>. <strong>(5, 1, -2) no</strong>: &#8467; = 1 allows m<sub>&#8467;</sub> = -1, 0, +1 only."},

// ===== 5. Electron configurations and orbital diagrams =====
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Which rule says electrons fill the lowest-energy orbitals first?",o:["the aufbau principle","Hund's rule","the Pauli exclusion principle","the Heisenberg uncertainty principle","the periodic law"],a:0,lec:'Handout 10: electron configurations',e:"<strong>Aufbau</strong> ('building up'): fill from the lowest energy upward, in the filling order on his orbital-ordering slide (1s, 2s, 2p, 3s, 3p, 4s, 3d, 4p, ...)."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"What does the Pauli exclusion principle require?",o:["no two electrons in an atom have the same four quantum numbers, so an orbital holds at most 2 electrons with opposite spins","electrons spread out across equal-energy orbitals before pairing","electrons fill the lowest energy orbitals first","an electron's position and speed cannot both be known","the 4s fills before the 3d"],a:0,lec:'Handout 10: electron configurations',e:"<strong>Pauli: max 2 electrons per orbital, and they must have opposite spins</strong> (one +&frac12;, one -&frac12;). Two up arrows in one box breaks it."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"What does Hund's rule say?",o:["within a subshell, put one electron in each orbital with parallel spins before pairing any","fill the lowest energy subshell first","an orbital holds at most 2 electrons","electrons pair up as soon as possible","half-filled subshells are unstable"],a:0,lec:'Handout 10: electron configurations',e:"<strong>Hund: spread out first, same spin, then pair.</strong> Carbon's two 2p electrons go in two different 2p boxes, both arrows up."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"This orbital diagram for carbon is WRONG. Which rule does it break?",d:OB([['1s','ud'],['2s','ud'],['2p','ud 0 0']]),o:["Hund's rule","the Pauli exclusion principle","the aufbau principle","the periodic law","nothing, it is correct"],a:0,lec:'Handout 10: orbital diagrams',e:"The two 2p electrons are paired in one box while two boxes sit empty. <strong>Hund's rule</strong> says put one in each first, spins parallel: 2p = &uarr; &uarr; _."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"This orbital diagram is WRONG. Which rule does it break?",d:OB([['1s','ud'],['2s','uu']]),o:["the Pauli exclusion principle","Hund's rule","the aufbau principle","the uncertainty principle","nothing, it is correct"],a:0,lec:'Handout 10: orbital diagrams',e:"Two electrons in the same orbital with the SAME spin would share all four quantum numbers. <strong>Pauli</strong> requires opposite spins: &uarr;&darr;."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"This diagram is offered as the GROUND STATE of beryllium. What is wrong?",d:OB([['1s','ud'],['2s','u'],['2p','u 0 0']]),o:["it breaks the aufbau principle: the 2s must fill before an electron goes to 2p","it breaks Hund's rule","it breaks the Pauli exclusion principle","beryllium has 5 electrons, not 4","nothing, it is the ground state"],a:0,lec:'Handout 10: orbital diagrams',e:"Be's ground state is 1s<sup>2</sup>2s<sup>2</sup>. Promoting an electron to 2p while 2s has room describes an <strong>excited state</strong>, so as a ground state it breaks <strong>aufbau</strong>."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Why does the 4s subshell fill before the 3d?",o:["penetration makes 4s lower in energy than 3d","3d orbitals are farther from the nucleus than 4s orbitals","the 4s has more orbitals than the 3d","d orbitals can never hold electrons in the 4th period","Hund's rule requires it"],a:0,lec:'Sep 25 lecture: ordering of orbitals',e:"His slide: <strong>penetration of the 4th and higher levels is so great that their s sublevel is lower in energy than the d sublevel of the previous level</strong>. Penetration is also why sublevels within one level are not degenerate (2s fills before 2p)."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Handout 10 #3a. Full ground-state configuration of nitrogen, and its valence electrons?",o:["1s<sup>2</sup>2s<sup>2</sup>2p<sup>3</sup>, 5 valence electrons","1s<sup>2</sup>2s<sup>2</sup>2p<sup>3</sup>, 3 valence electrons","1s<sup>2</sup>2s<sup>2</sup>2p<sup>5</sup>, 7 valence electrons","1s<sup>2</sup>2p<sup>5</sup>, 5 valence electrons","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>1</sup>, 1 valence electron"],a:0,lec:'Handout 10 and the Sep 28 lecture',e:"N has 7 electrons: <strong>1s<sup>2</sup>2s<sup>2</sup>2p<sup>3</sup> = [He]2s<sup>2</sup>2p<sup>3</sup></strong>. Valence electrons are everything in the outermost shell, 2s<sup>2</sup> + 2p<sup>3</sup> = <strong>5</strong>, which matches group 5A. Counting only the p electrons gives the trap answer 3."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Handout 10 #3b. Noble-gas configuration of calcium?",o:["[Ar]4s<sup>2</sup>","[Ar]3d<sup>2</sup>","[Ne]3s<sup>2</sup>","[Kr]4s<sup>2</sup>","[Ar]4s<sup>1</sup>3d<sup>1</sup>"],a:0,lec:'Handout 10 and the Sep 28 lecture',e:"Ca (20 e<sup>-</sup>) = 1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>4s<sup>2</sup> = <strong>[Ar]4s<sup>2</sup></strong>, 2 valence electrons. The 4s fills before the 3d."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Handout 10 #3c. Noble-gas configuration of manganese?",o:["[Ar]3d<sup>5</sup>4s<sup>2</sup>","[Ar]3d<sup>7</sup>","[Ar]3d<sup>6</sup>4s<sup>1</sup>","[Ar]4s<sup>2</sup>4p<sup>5</sup>","[Kr]3d<sup>5</sup>4s<sup>2</sup>"],a:0,lec:'Handout 10 and the Sep 28 lecture',e:"Mn (25 e<sup>-</sup>) = <strong>[Ar]3d<sup>5</sup>4s<sup>2</sup></strong>, his answer. Written in filling order it is [Ar]4s<sup>2</sup>3d<sup>5</sup>; his note says Knewton wants the filling order. It is the same configuration either way. Mn is not an exception: d<sup>5</sup> is reached normally."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Handout 10 #3d. Noble-gas configuration of silver?",o:["[Kr]4d<sup>10</sup>5s<sup>1</sup>","[Kr]4d<sup>9</sup>5s<sup>2</sup>","[Kr]5s<sup>2</sup>5p<sup>9</sup>","[Xe]4d<sup>10</sup>5s<sup>1</sup>","[Kr]4d<sup>10</sup>5s<sup>2</sup>"],a:0,lec:'Handout 10 and the Sep 28 lecture',e:"Expected [Kr]5s<sup>2</sup>4d<sup>9</sup>, but his note: <strong>5s<sup>2</sup>4d<sup>9</sup> changes to 5s<sup>1</sup>4d<sup>10</sup> because atoms prefer half- or fully-filled subshells</strong>. Answer: <strong>[Kr]4d<sup>10</sup>5s<sup>1</sup></strong>. That is the d<sup>9</sup> &rarr; d<sup>10</sup> exception."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Chapter 3 Worksheet #10b. Full ground-state configuration of chromium?",o:["1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>5</sup>4s<sup>1</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>4</sup>4s<sup>2</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>6</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>4s<sup>2</sup>4p<sup>4</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>5</sup>4s<sup>2</sup>"],a:0,lec:'Chapter 3 Review Worksheet',e:"Cr is the <strong>d<sup>4</sup> &rarr; d<sup>5</sup> exception</strong>: one 4s electron moves into 3d to make a half-filled d subshell. 3d<sup>4</sup>4s<sup>2</sup> is what the filling order predicts, and it is the trap. 3d<sup>5</sup>4s<sup>2</sup> is manganese."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Noble-gas configuration of copper?",o:["[Ar]3d<sup>10</sup>4s<sup>1</sup>","[Ar]3d<sup>9</sup>4s<sup>2</sup>","[Ar]3d<sup>10</sup>4s<sup>2</sup>","[Ar]4s<sup>2</sup>4p<sup>9</sup>","[Kr]3d<sup>9</sup>4s<sup>2</sup>"],a:0,lec:'Sep 28 lecture: exceptions',e:"Cu is the <strong>d<sup>9</sup> &rarr; d<sup>10</sup> exception</strong>, the same pattern as Ag directly below it. [Ar]3d<sup>10</sup>4s<sup>2</sup> is zinc."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Which pair of predicted configurations gets 'converted' by the exception rule on the study guide?",o:["d<sup>4</sup> becomes d<sup>5</sup>, and d<sup>9</sup> becomes d<sup>10</sup>, by moving one s electron into the d subshell","d<sup>5</sup> becomes d<sup>4</sup>, and d<sup>10</sup> becomes d<sup>9</sup>","p<sup>2</sup> becomes p<sup>3</sup>, and p<sup>5</sup> becomes p<sup>6</sup>","s<sup>1</sup> becomes s<sup>2</sup> in every transition metal","d<sup>3</sup> becomes d<sup>5</sup>, and d<sup>8</sup> becomes d<sup>10</sup>"],a:0,lec:'Exam 2 study guide, topic 8c',e:"Study guide topic 8c: <strong>the exceptions of d<sup>4</sup>/d<sup>9</sup> to d<sup>5</sup>/d<sup>10</sup> conversions</strong>. Half-filled (d<sup>5</sup>) and filled (d<sup>10</sup>) subshells are extra stable, so one electron moves from the s into the d. The groups to watch: Cr and Mo (d<sup>5</sup>s<sup>1</sup>), Cu and Ag (d<sup>10</sup>s<sup>1</sup>)."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Which element has the configuration 1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>5</sup>?",o:["chlorine","argon","sulfur","fluorine","bromine"],a:0,lec:'Sep 28 lecture: identifying an element',e:"His method: <strong>read the last term, 3p<sup>5</sup>, as row 3, p block, 5th element across</strong> &rarr; Cl. Or add the superscripts: 2 + 2 + 6 + 2 + 5 = 17 = Cl."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Which element has the configuration [Ar]3d<sup>10</sup>4s<sup>2</sup>4p<sup>3</sup>?",o:["arsenic","phosphorus","vanadium","antimony","selenium"],a:0,lec:'Sep 28 lecture: identifying an element',e:"4p<sup>3</sup> = row 4, p block, 3rd element &rarr; <strong>As</strong>. Check: 18 + 10 + 2 + 3 = 33. Phosphorus is the 3p<sup>3</sup> element above it."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Chapter 3 Worksheet #11a. Noble-gas configuration of germanium?",o:["[Ar]3d<sup>10</sup>4s<sup>2</sup>4p<sup>2</sup>","[Ar]4s<sup>2</sup>4p<sup>2</sup>","[Ar]3d<sup>10</sup>4s<sup>2</sup>4p<sup>4</sup>","[Kr]4s<sup>2</sup>4p<sup>2</sup>","[Ar]3d<sup>12</sup>4s<sup>2</sup>"],a:0,lec:'Chapter 3 Review Worksheet',e:"Ge (32 e<sup>-</sup>) = <strong>[Ar]3d<sup>10</sup>4s<sup>2</sup>4p<sup>2</sup></strong>. The trap is skipping the 3d<sup>10</sup>: by the time you reach the 4p block, the 3d is full. Check the count: 18 + 10 + 2 + 2 = 32."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Chapter 3 Worksheet #11b. Noble-gas configuration of tin?",o:["[Kr]4d<sup>10</sup>5s<sup>2</sup>5p<sup>2</sup>","[Kr]5s<sup>2</sup>5p<sup>2</sup>","[Xe]5s<sup>2</sup>5p<sup>2</sup>","[Kr]4d<sup>10</sup>5s<sup>2</sup>5p<sup>4</sup>","[Ar]4d<sup>10</sup>5s<sup>2</sup>5p<sup>2</sup>"],a:0,lec:'Chapter 3 Review Worksheet',e:"Sn (50 e<sup>-</sup>) sits directly below Ge, so it has the same ending one shell up: <strong>[Kr]4d<sup>10</sup>5s<sup>2</sup>5p<sup>2</sup></strong>. 36 + 10 + 2 + 2 = 50."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Chapter 3 Worksheet #10a. Full configuration of fluorine?",o:["1s<sup>2</sup>2s<sup>2</sup>2p<sup>5</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>7</sup>","1s<sup>2</sup>2p<sup>7</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>3</sup>"],a:0,lec:'Chapter 3 Review Worksheet',e:"F has 9 electrons: <strong>1s<sup>2</sup>2s<sup>2</sup>2p<sup>5</sup></strong>, 7 valence electrons (group 7A). 2p<sup>6</sup> is the fluoride ion, F<sup>-</sup>."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"How many UNPAIRED electrons does a ground-state oxygen atom have?",d:OB([['1s','ud'],['2s','ud'],['2p','ud u u']]),o:["2","0","4","6","1"],a:0,lec:'Handout 10: orbital diagrams',e:"O = 1s<sup>2</sup>2s<sup>2</sup>2p<sup>4</sup>. By Hund's rule the four 2p electrons go &uarr;&darr; &uarr; &uarr;, leaving <strong>2 unpaired</strong>, so the O atom is paramagnetic."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Handout 10 #1-2. Configuration of a lithium atom?",o:["1s<sup>2</sup>2s<sup>1</sup>","1s<sup>3</sup>","1s<sup>2</sup>2p<sup>1</sup>","1s<sup>1</sup>2s<sup>2</sup>","[He]2s<sup>2</sup>"],a:0,lec:'Handout 10 and the Sep 23 lecture',e:"Li has 3 electrons. 1s holds 2 (Pauli), the third goes to 2s (aufbau, before 2p): <strong>1s<sup>2</sup>2s<sup>1</sup></strong>. 1s<sup>3</sup> breaks Pauli."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"Molybdenum (Mo) is directly below chromium. What is its noble-gas configuration?",o:["[Kr]4d<sup>5</sup>5s<sup>1</sup>","[Kr]4d<sup>4</sup>5s<sup>2</sup>","[Kr]4d<sup>6</sup>","[Ar]4d<sup>5</sup>5s<sup>1</sup>","[Kr]5s<sup>2</sup>5p<sup>4</sup>"],a:0,lec:'Sep 28 lecture: exceptions',e:"Same group as Cr, same <strong>d<sup>4</sup> &rarr; d<sup>5</sup></strong> shift: <strong>[Kr]4d<sup>5</sup>5s<sup>1</sup></strong>. The exception follows the column."},
{chId:'econf',ch:'Configurations and Orbital Diagrams',q:"How many electrons are in the 3d subshell of a neutral iron atom?",o:["6","8","2","26","5"],a:0,lec:'Handout 10: electron configurations',e:"Fe (26 e<sup>-</sup>) = [Ar]3d<sup>6</sup>4s<sup>2</sup>. <strong>6 in the 3d</strong>. Count across the d block: Sc d<sup>1</sup>, Ti d<sup>2</sup>, V d<sup>3</sup>, (Cr), Mn d<sup>5</sup>, Fe d<sup>6</sup>."},

// ===== 6. Ions, magnetism, core and valence =====
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Why do atoms form the ions they do?",o:["to become isoelectronic with the nearest noble gas, because filled shells are lower in energy","to gain as many electrons as possible","to make their protons equal their neutrons","to lose all their valence and core electrons","to become paramagnetic"],a:0,lec:'Video 1: ion formation',e:"His Video 1 board: the <strong>goal is to be isoelectronic (same total number of electrons) with the nearest noble gas</strong>, because <strong>filled shells are stable in energy</strong>. Nonmetals fill their current shell; metals empty theirs."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Video 1. Noble-gas configuration of Fe<sup>2+</sup>?",o:["[Ar]3d<sup>6</sup>","[Ar]3d<sup>4</sup>4s<sup>2</sup>","[Ar]3d<sup>8</sup>","[Ar]3d<sup>6</sup>4s<sup>2</sup>","[Ar]3d<sup>5</sup>4s<sup>1</sup>"],a:0,lec:'Video 1: ions and magnetism',e:"Fe = [Ar]3d<sup>6</sup>4s<sup>2</sup>. <strong>Transition metals lose their 4s electrons first</strong>, so Fe<sup>2+</sup> = [Ar]3d<sup>6</sup>4s<sup>0</sup> = <strong>[Ar]3d<sup>6</sup></strong>, exactly as he wrote it. Taking the two from the 3d gives the trap [Ar]3d<sup>4</sup>4s<sup>2</sup>."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Chapter 3 Worksheet #10c. Full configuration of Cr<sup>+</sup>?",o:["1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>5</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>4</sup>4s<sup>1</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>3</sup>4s<sup>2</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>5</sup>4s<sup>1</sup>","1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>6</sup>3d<sup>6</sup>"],a:0,lec:'Chapter 3 Review Worksheet',e:"Cr = ...3d<sup>5</sup>4s<sup>1</sup>. His key: <strong>the higher energy electron in the 4s subshell was removed before a 3d electron, even though the 3d fills after the 4s</strong>. So Cr<sup>+</sup> = ...3p<sup>6</sup><strong>3d<sup>5</sup></strong>. ...3d<sup>5</sup>4s<sup>1</sup> is neutral Cr, not the ion."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Chapter 3 Worksheet #11c. Noble-gas configuration of Sn<sup>4+</sup>?",o:["[Kr]4d<sup>10</sup>","[Kr]4d<sup>6</sup>5s<sup>2</sup>5p<sup>2</sup>","[Kr]5s<sup>2</sup>5p<sup>2</sup>","[Kr]4d<sup>10</sup>5s<sup>2</sup>","[Xe]"],a:0,lec:'Chapter 3 Review Worksheet',e:"Sn = [Kr]4d<sup>10</sup>5s<sup>2</sup>5p<sup>2</sup>. Remove 4 electrons from the outermost shell (n = 5): the two 5p, then the two 5s. <strong>Sn<sup>4+</sup> = [Kr]4d<sup>10</sup></strong>. [Kr]4d<sup>10</sup>5s<sup>2</sup> would be Sn<sup>2+</sup>."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Chapter 3 Worksheet #9. Configuration of the potassium ion, K<sup>+</sup>?",o:["[Ar], with 18 electrons","[Ar]4s<sup>1</sup>, with 19 electrons","[Ar]4s<sup>2</sup>, with 20 electrons","[Ne]3s<sup>2</sup>3p<sup>5</sup>, with 17 electrons","[Kr], with 36 electrons"],a:0,lec:'Chapter 3 Review Worksheet',e:"K = [Ar]4s<sup>1</sup> (19 e<sup>-</sup>). Losing its one valence electron gives <strong>K<sup>+</sup> = [Ar], 18 electrons</strong>, isoelectronic with argon."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Which ion has the configuration [Ar]3d<sup>5</sup>?",o:["Fe<sup>3+</sup>","Fe<sup>2+</sup>","Mn<sup>3+</sup>","Cr<sup>3+</sup>","Co<sup>2+</sup>"],a:0,lec:'Video 1: ions and magnetism',e:"Fe = [Ar]3d<sup>6</sup>4s<sup>2</sup>. Remove both 4s, then one 3d: <strong>Fe<sup>3+</sup> = [Ar]3d<sup>5</sup></strong>. Fe<sup>2+</sup> is 3d<sup>6</sup>, Mn<sup>3+</sup> is 3d<sup>4</sup>, Cr<sup>3+</sup> is 3d<sup>3</sup>, Co<sup>2+</sup> is 3d<sup>7</sup>."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"An atom has the configuration 1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>4</sup>. What ion does it form?",o:["S<sup>2-</sup>","S<sup>2+</sup>","S<sup>6+</sup>","S<sup>4-</sup>","Ar<sup>-</sup>"],a:0,lec:'Exam 2 study guide, topic 9',e:"3p<sup>4</sup> is sulfur, 6 valence electrons, 2 short of argon's full shell. <strong>Gaining 2 electrons is easier than losing 6, so S<sup>2-</sup></strong>. Topic 9 is exactly this: predict the charge from the configuration."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"What does DIAMAGNETIC mean?",o:["all electrons are paired, so the species is slightly repelled by a magnetic field","it has at least one unpaired electron and is attracted to a magnetic field","it has no electrons","it is a permanent magnet","it contains an odd number of protons"],a:0,lec:'Video 1: magnetic properties',e:"His Video 1 slide: <strong>diamagnetic = all electrons paired; slightly repels a magnetic field</strong>. <strong>Paramagnetic = at least 1 unpaired electron; attracts a magnetic field.</strong> Decide from the orbital diagram."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Chapter 3 Worksheet #12. Which form of vanadium is diamagnetic: V, V<sup>+</sup>, V<sup>2+</sup>, V<sup>3+</sup>, V<sup>4+</sup> or V<sup>5+</sup>?",o:["V<sup>5+</sup> only","V only","V<sup>2+</sup> and V<sup>4+</sup>","V<sup>3+</sup> and V<sup>5+</sup>","none of them"],a:0,lec:'Chapter 3 Review Worksheet',e:"V = [Ar]3d<sup>3</sup>4s<sup>2</sup>. His drawings remove the 4s first: V<sup>+</sup> [Ar]3d<sup>3</sup>4s<sup>1</sup>, V<sup>2+</sup> [Ar]3d<sup>3</sup>, V<sup>3+</sup> [Ar]3d<sup>2</sup>, V<sup>4+</sup> [Ar]3d<sup>1</sup>, all with unpaired electrons. <strong>V<sup>5+</sup> = [Ar]</strong>: every electron is a paired core electron, so only V<sup>5+</sup> is diamagnetic."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Is Zn<sup>2+</sup> paramagnetic or diamagnetic?",o:["diamagnetic: [Ar]3d<sup>10</sup>, every electron paired","paramagnetic: [Ar]3d<sup>8</sup>4s<sup>2</sup>, two unpaired","paramagnetic: [Ar]3d<sup>10</sup>, ten unpaired","diamagnetic: [Ar]4s<sup>2</sup>","paramagnetic: it is a metal ion"],a:0,lec:'Video 1: magnetic properties',e:"Zn = [Ar]3d<sup>10</sup>4s<sup>2</sup> &rarr; lose the 4s &rarr; <strong>Zn<sup>2+</sup> = [Ar]3d<sup>10</sup></strong>, a full d subshell with 5 paired boxes. <strong>Diamagnetic.</strong>"},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Video 1. How many unpaired electrons does Fe<sup>2+</sup> have?",d:OB([['3d','ud u u u u'],['4s','0']]),o:["4, so it is paramagnetic","0, so it is diamagnetic","6, so it is paramagnetic","2, so it is paramagnetic","1, so it is paramagnetic"],a:0,lec:'Video 1: ions and magnetism',e:"Fe<sup>2+</sup> = [Ar]3d<sup>6</sup>. Five boxes, six electrons: one each first (Hund), then the sixth pairs up. <strong>4 unpaired, paramagnetic</strong>, as he showed in Video 1."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Is the fluoride ion, F<sup>-</sup>, paramagnetic or diamagnetic?",o:["diamagnetic: [He]2s<sup>2</sup>2p<sup>6</sup>, all paired","paramagnetic: one unpaired 2p electron","paramagnetic: it carries a negative charge","diamagnetic: it has no electrons in 2p","paramagnetic: [He]2s<sup>2</sup>2p<sup>5</sup>"],a:0,lec:'Video 1: ions and magnetism',e:"F<sup>-</sup> gains one electron to fill 2p: <strong>[He]2s<sup>2</sup>2p<sup>6</sup>, all paired, diamagnetic</strong>. His Video 1 example. The neutral F atom (2p<sup>5</sup>) has 1 unpaired electron and is paramagnetic."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Handout 11 #1. How many valence electrons does a selenium atom have?",o:["6","4","16","34","2"],a:0,lec:'Handout 11 and the Oct 5 lecture',e:"His Oct 5 answer: <strong>6</strong>, because <strong># valence electrons = group A number</strong> and Se is in 6A. In configuration terms: [Ar]3d<sup>10</sup><strong>4s<sup>2</sup>4p<sup>4</sup></strong>; the 3d<sup>10</sup> is not in the outer shell."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"How many CORE electrons does a chlorine atom have?",o:["10","7","17","8","2"],a:0,lec:'Exam 2 study guide, topic 12',e:"Cl = [Ne]3s<sup>2</sup>3p<sup>5</sup>. Valence = the outer shell, 3s<sup>2</sup>3p<sup>5</sup> = 7. <strong>Core = everything inside, the [Ne] = 10</strong>. 17 total = 10 core + 7 valence."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Gallium is in group 3A and has 31 electrons. How many are core electrons?",o:["28","3","18","13","10"],a:0,lec:'Exam 2 study guide, topic 12',e:"Ga = [Ar]3d<sup>10</sup>4s<sup>2</sup>4p<sup>1</sup>. Valence = 4s<sup>2</sup>4p<sup>1</sup> = 3 (group 3A). <strong>Core = 31 - 3 = 28</strong>: the 18 in [Ar] plus the filled 3d<sup>10</sup>. Forgetting the 3d gives 18."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"An element has the configuration [Ne]3s<sup>2</sup>. What ion does it most likely form?",o:["Mg<sup>2+</sup>","Mg<sup>2-</sup>","Na<sup>+</sup>","Mg<sup>6-</sup>","Al<sup>3+</sup>"],a:0,lec:'Exam 2 study guide, topic 9',e:"[Ne]3s<sup>2</sup> is magnesium, 2 valence electrons. Losing 2 empties the shell and leaves [Ne]: <strong>Mg<sup>2+</sup></strong>. Metals empty their shell; nonmetals fill theirs."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Which describes Cu<sup>+</sup> and Cu<sup>2+</sup>?",o:["Cu<sup>+</sup> is [Ar]3d<sup>10</sup> and diamagnetic; Cu<sup>2+</sup> is [Ar]3d<sup>9</sup> and paramagnetic","both are diamagnetic","both are paramagnetic","Cu<sup>+</sup> is [Ar]3d<sup>9</sup>4s<sup>1</sup>; Cu<sup>2+</sup> is [Ar]3d<sup>9</sup>","Cu<sup>+</sup> is [Ar]3d<sup>8</sup>4s<sup>2</sup>; Cu<sup>2+</sup> is [Ar]3d<sup>8</sup>4s<sup>1</sup>"],a:0,lec:'Video 1: ions and magnetism',e:"Cu = [Ar]3d<sup>10</sup>4s<sup>1</sup> (exception). Lose the 4s<sup>1</sup>: <strong>Cu<sup>+</sup> = [Ar]3d<sup>10</sup>, all paired, diamagnetic</strong>. Lose one more from 3d: <strong>Cu<sup>2+</sup> = [Ar]3d<sup>9</sup>, one unpaired, paramagnetic</strong>."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Which pair is ISOELECTRONIC?",o:["Na<sup>+</sup> and F<sup>-</sup>","Na and F","Na<sup>+</sup> and Cl<sup>-</sup>","K<sup>+</sup> and Ne","Mg<sup>2+</sup> and Ar"],a:0,lec:'Video 1: ion formation',e:"Isoelectronic = <strong>same total number of electrons</strong>. Na<sup>+</sup> (11 - 1) and F<sup>-</sup> (9 + 1) both have <strong>10</strong>, the same as Ne. Cl<sup>-</sup> has 18."},
{chId:'ions',ch:'Ions, Magnetism, Valence',q:"Noble-gas configuration of Ti<sup>2+</sup>?",o:["[Ar]3d<sup>2</sup>","[Ar]4s<sup>2</sup>","[Ar]3d<sup>4</sup>","[Ar]3d<sup>2</sup>4s<sup>2</sup>","[Ar]"],a:0,lec:'Video 1: ions and magnetism',e:"Ti = [Ar]3d<sup>2</sup>4s<sup>2</sup>. 4s leaves first: <strong>Ti<sup>2+</sup> = [Ar]3d<sup>2</sup></strong>. [Ar]4s<sup>2</sup> is what you get by wrongly taking the d electrons; [Ar] alone is Ti<sup>4+</sup>."},

// ===== 7. Periodic table organization =====
{chId:'ptable',ch:'Periodic Table Layout',q:"How is the periodic table organized?",o:["7 periods (rows) and 18 groups (columns)","18 periods (rows) and 7 groups (columns)","8 periods and 8 groups","7 groups and 18 blocks","by atomic mass, heaviest at the top"],a:0,lec:'Sep 25 lecture: organizing the elements',e:"<strong>7 periods (rows), 18 groups (columns).</strong> Arranged by atomic number. Elements in a group have the same number of valence electrons, which is why they behave alike."},
{chId:'ptable',ch:'Periodic Table Layout',q:"Why do elements in the same column have similar properties (the periodic law)?",o:["they have the same number of valence electrons, and valence-electron count repeats periodically","they have the same atomic mass","they have the same number of shells","they all have full outer shells","they all have the same number of neutrons"],a:0,lec:'Video 2: periodic table',e:"His Video 2 opening: properties are similar by column and row and change in a regular way <strong>because the number of valence electrons is periodic</strong>. Same column = same valence count = similar chemistry."},
{chId:'ptable',ch:'Periodic Table Layout',q:"Which is a property of METALS?",o:["they tend to form cations and conduct heat and electricity well","they tend to form anions","they are brittle solids that do not conduct","they are found on the right side of the table","most are gases at room temperature"],a:0,lec:'Video 2: periodic table',e:"His Video 2 slide: metals (94 of 118 elements) sit on the <strong>left</strong>, typically <strong>form cations</strong>, are <strong>good conductors</strong> of heat and electricity, malleable and ductile, and solid at room temperature (Hg is the liquid). Nonmetals are the opposite."},
{chId:'ptable',ch:'Periodic Table Layout',q:"Which is a property of NONMETALS?",o:["they tend to form anions and conduct heat and electricity poorly","they are malleable and ductile","they form cations","they are all solids","they make up most of the table"],a:0,lec:'Video 2: periodic table',e:"Nonmetals (18 of 118) sit on the <strong>right</strong>, typically <strong>form anions</strong>, and are <strong>poor conductors</strong>. 11 are gases, 1 is a liquid (Br<sub>2</sub>), and 6 are brittle solids (C, P, S, Se, I<sub>2</sub>, At)."},
{chId:'ptable',ch:'Periodic Table Layout',q:"Which element is a METALLOID?",o:["silicon (Si)","aluminum (Al)","phosphorus (P)","magnesium (Mg)","sulfur (S)"],a:0,lec:'Video 2: periodic table',e:"Metalloids sit along the staircase between metals and nonmetals: B, <strong>Si</strong>, Ge, As, Sb, Te. His example is Si: <strong>shiny like a metal, brittle like a nonmetal, and can conduct electricity</strong>. Al is a metal; P and S are nonmetals."},
{chId:'ptable',ch:'Periodic Table Layout',q:"Which element is NOT one of the seven diatomic elements?",o:["sulfur","bromine","nitrogen","hydrogen","iodine"],a:0,lec:'Oct 7 lecture: organization of matter',e:"The seven diatomics: <strong>Br<sub>2</sub>, I<sub>2</sub>, N<sub>2</sub>, Cl<sub>2</sub>, H<sub>2</sub>, O<sub>2</sub>, F<sub>2</sub></strong> (BrINClHOF). <strong>Sulfur is polyatomic, S<sub>8</sub></strong>, and phosphorus is P<sub>4</sub>."},
{chId:'ptable',ch:'Periodic Table Layout',q:"Why is the d block 10 columns wide?",o:["five d orbitals hold 10 electrons, so 10 elements fill the d subshell","there are 10 transition metals in total","d orbitals hold 1 electron each","the d block has 10 periods","each d orbital holds 10 electrons"],a:0,lec:'Sep 25 lecture: orbital blocks',e:"His slide: <strong>one s orbital holds 2 e<sup>-</sup> &rarr; 2 elements (s block); three p &rarr; 6 (p block); five d &rarr; 10 (d block); seven f &rarr; 14 (f block)</strong>. The table's shape IS the orbital structure."},
{chId:'ptable',ch:'Periodic Table Layout',q:"What are the 'A' group elements, the 'B' group elements, and the two rows at the bottom called?",o:["main group, transition metals, inner transition metals","transition metals, main group, noble gases","metals, nonmetals, metalloids","s block, p block, d block","alkali metals, halogens, noble gases"],a:0,lec:'Sep 25 lecture: classifying the elements',e:"His color-coded slide: <strong>main group = A groups</strong> (s and p blocks), <strong>transition metals = B groups</strong> (d block), <strong>inner transition metals = the f-block rows</strong> at the bottom."},
{chId:'ptable',ch:'Periodic Table Layout',q:"An element is in group 5A. How many valence electrons does it have?",o:["5","3","15","8","2"],a:0,lec:'Sep 23 lecture: position vs valence electrons',e:"His rule: <strong># of valence electrons = group A number</strong>. Group 5A (N, P, As) has 5: ns<sup>2</sup>np<sup>3</sup>."},
{chId:'ptable',ch:'Periodic Table Layout',q:"Which element is in the d block?",o:["iron (Fe)","calcium (Ca)","bromine (Br)","neon (Ne)","sodium (Na)"],a:0,lec:'Sep 25 lecture: orbital blocks',e:"Fe ([Ar]3d<sup>6</sup>4s<sup>2</sup>) fills the 3d: <strong>d block, a transition metal</strong>. Ca and Na are s block; Br and Ne are p block."},
{chId:'ptable',ch:'Periodic Table Layout',q:"Which pair lists the group name with its column correctly?",o:["halogens = group 7A","noble gases = group 1A","alkali metals = group 7A","alkaline earth metals = group 8A","halogens = group 2A"],a:0,lec:'Video 2: periodic table',e:"<strong>1A alkali metals, 2A alkaline earth metals, 7A halogens, 8A noble gases.</strong> Halogens (F, Cl, Br, I) gain 1 electron to become -1 ions."},

// ===== 8. Periodic trends =====
{chId:'trends',ch:'Periodic Trends',q:"Handout 11 #3. Which is larger, S or O?",o:["S, because it has more occupied shells","O, because it has fewer electrons to repel","they are the same size","O, because it is more electronegative","S, because it has a higher effective nuclear charge"],a:0,lec:'Handout 11 and the Oct 5 lecture',e:"S is directly below O. <strong>Down a column, the size of the outermost occupied orbital increases</strong> (n = 3 vs n = 2), so <strong>S is larger</strong>."},
{chId:'trends',ch:'Periodic Trends',q:"Handout 11 #4A. Which is smaller, Mg or Mg<sup>2+</sup>?",o:["Mg<sup>2+</sup>","Mg","they are the same size","it depends on the temperature","Mg<sup>2+</sup> is larger because it is charged"],a:0,lec:'Handout 11 and Video 2',e:"Mg<sup>2+</sup> lost its entire n = 3 shell (both 3s electrons). <strong>Cations are smaller than their atoms</strong>; his Video 2 slide says cation radius roughly halves (Na 186 pm &rarr; Na<sup>+</sup> 95 pm)."},
{chId:'trends',ch:'Periodic Trends',q:"Handout 11 #4B. Which is SMALLEST: K<sup>+</sup>, Ca<sup>2+</sup>, S<sup>2-</sup> or Cl<sup>-</sup>?",o:["Ca<sup>2+</sup>","K<sup>+</sup>","S<sup>2-</sup>","Cl<sup>-</sup>","they are all the same size"],a:0,lec:'Handout 11 and the Oct 5 lecture',e:"His Oct 5 note: <strong>all of these species are isoelectronic (18 e<sup>-</sup>), so the one with the most protons is the smallest</strong>. Ca has 20 protons pulling on 18 electrons. Order: Ca<sup>2+</sup> &lt; K<sup>+</sup> &lt; Cl<sup>-</sup> &lt; S<sup>2-</sup>."},
{chId:'trends',ch:'Periodic Trends',q:"Handout 11 #5. Which has the larger FIRST ionization energy, Ca or Cl?",o:["Cl","Ca","they are equal","Ca, because it is a metal","neither has an ionization energy"],a:0,lec:'Handout 11 and the Oct 5 lecture',e:"Ionization energy <strong>increases across a row</strong> (effective nuclear charge rises) and <strong>decreases down a column</strong>. Cl is up and to the right of Ca, so <strong>Cl holds its electron harder</strong>."},
{chId:'trends',ch:'Periodic Trends',q:"Handout 11 #6. Which is higher: the 2nd ionization energy of K, or the 2nd ionization energy of Ca?",o:["IE<sub>2</sub> of K, because it removes a core electron","IE<sub>2</sub> of Ca, because Ca has more protons","they are equal","IE<sub>2</sub> of Ca, because it removes a core electron","neither can be compared"],a:0,lec:'Handout 11 and the Oct 5 lecture',e:"His answer: <strong>IE<sub>2</sub> of K removes a core electron</strong> (K<sup>+</sup> is already [Ar]), while <strong>IE<sub>2</sub> of Ca removes a valence electron</strong> (its second 4s). Core electrons take far more energy to remove."},
{chId:'trends',ch:'Periodic Trends',q:"Chapter 3 Worksheet #13f. Which is higher: IE<sub>3</sub> of Be or IE<sub>3</sub> of B?",o:["IE<sub>3</sub> of Be","IE<sub>3</sub> of B","they are equal","IE<sub>3</sub> of B, because B is farther right","neither element has a third ionization energy"],a:0,lec:'Chapter 3 Review Worksheet',e:"Be has 2 valence electrons, B has 3. <strong>The third electron removed from Be is a core electron</strong>; from B it is still a valence electron. His key: core electrons always require a lot more energy to remove."},
{chId:'trends',ch:'Periodic Trends',q:"Chapter 3 Worksheet #13c. Rank from SMALLEST to LARGEST: Cl, I, Se, Sr.",o:["Cl &lt; Se &lt; I &lt; Sr","Sr &lt; I &lt; Se &lt; Cl","Cl &lt; I &lt; Se &lt; Sr","Se &lt; Cl &lt; I &lt; Sr","I &lt; Cl &lt; Sr &lt; Se"],a:0,lec:'Chapter 3 Review Worksheet',e:"His key: <strong>larger atoms are farther left and down</strong>. Cl (period 3) is smallest; Se is period 4 but right side; I is period 5 right side; Sr is period 5 far left, the largest. <strong>Cl &lt; Se &lt; I &lt; Sr.</strong>"},
{chId:'trends',ch:'Periodic Trends',q:"Chapter 3 Worksheet #13d. Which has the LARGEST radius: Sr<sup>2+</sup>, Sr or Sr<sup>2-</sup>?",o:["Sr<sup>2-</sup>","Sr","Sr<sup>2+</sup>","all three are equal","Sr<sup>2+</sup>, because it is most charged"],a:0,lec:'Chapter 3 Review Worksheet',e:"His key: <strong>adding electrons increases electron-electron repulsion, so the species swells</strong> as the electrons push away from each other. More electrons on the same nucleus = bigger: Sr<sup>2+</sup> &lt; Sr &lt; Sr<sup>2-</sup>."},
{chId:'trends',ch:'Periodic Trends',q:"Chapter 3 Worksheet #13b. Which atom has the LEAST metallic character: K, O or P?",o:["O","K","P","they are equal","K, because it is in period 4"],a:0,lec:'Chapter 3 Review Worksheet',e:"Metallic character <strong>increases down and to the left</strong>. His key: <strong>O is farthest up and to the right</strong>, so it has the least. K is the most metallic of the three."},
{chId:'trends',ch:'Periodic Trends',q:"Chapter 3 Worksheet #13e. Which has the higher first ionization energy, Li or S?",o:["S","Li","they are equal","Li, because it is smaller","neither, both are metals"],a:0,lec:'Chapter 3 Review Worksheet',e:"S is <strong>five groups farther right</strong> (6A vs 1A), and that outweighs it being one row lower. His key says 'farthest up and to the right', but only 'right' is true here: S is in period 3, Li in period 2. Li loses its single 2s electron easily."},
{chId:'trends',ch:'Periodic Trends',q:"Why does atomic radius DECREASE from left to right across a period?",o:["effective nuclear charge increases, pulling the same shell in tighter","more shells are added","electrons repel each other more","the atoms lose electrons","the number of neutrons decreases"],a:0,lec:'Video 2: periodic trends',e:"Across a row the electrons go into the same shell while protons are added. Shielding barely changes, so <strong>Z<sub>eff</sub> = Z - S rises</strong> and the outer electrons are pulled closer. His summary table gives this reason for both radius (down across) and IE (up across)."},
{chId:'trends',ch:'Periodic Trends',q:"Why does atomic radius INCREASE going down a group?",o:["the outermost occupied orbital is larger (higher n)","effective nuclear charge increases","the atoms gain protons, which push electrons away","electronegativity increases","the atoms become ions"],a:0,lec:'Video 2: periodic trends',e:"His summary: down a column, <strong>the size of the outermost occupied orbital increases</strong>. Each step down adds a shell (n goes up)."},
{chId:'trends',ch:'Periodic Trends',q:"What is the first ionization energy?",o:["the energy required to remove one electron from a gaseous atom","the energy released when an atom gains an electron","the attraction an atom has for shared electrons in a bond","the energy of the photon an atom emits","the size of an atom"],a:0,lec:'Video 2: periodic trends',e:"His Video 2 slide: <strong>energy required to remove 1 electron from a gaseous atom</strong>, one at a time. Higher energy means the electron is harder to remove. 'Energy released when an atom gains an electron' is electron affinity; 'attraction for shared electrons in a bond' is electronegativity."},
{chId:'trends',ch:'Periodic Trends',q:"According to his summary slide, how does electron affinity change?",o:["across a row it becomes more negative; down a column there is no definite trend","across a row it becomes more positive; down a column it becomes more negative","it increases down a column and decreases across a row","it is the same for every element","it becomes more negative down a column only"],a:0,lec:'Video 2: periodic trends',e:"His summary table: electron affinity, <strong>across a row: decreasing (more negative)</strong>, because effective nuclear charge increases; <strong>down a column: no definite trend</strong>. A more negative EA means a greater attraction for an extra electron."},
{chId:'trends',ch:'Periodic Trends',q:"Which atom has the MOST NEGATIVE electron affinity?",o:["Cl","Na","Mg","Ne","Ca"],a:0,lec:'Video 2: periodic trends',e:"His Video 2 values: <strong>Cl -349 kJ/mol</strong> (the most negative of all), F -328, Br -325. Mg and Ne show values above 0 (they do not want an extra electron), and Ca is about -2. Halogens grab one electron to complete their shell."},
{chId:'trends',ch:'Periodic Trends',q:"Oct 5 pop quiz. Which group 1A metal reacts most vigorously with water: Li, Na or K?",o:["K, because its lower ionization energy lets it lose its electron most easily","Li, because it is the smallest","Na, because it is in the middle","they react equally","Li, because it has the highest ionization energy"],a:0,lec:'Oct 5 lecture: class pop quiz',e:"His answer: <strong>potassium. The lower ionization energy means the electron is not held as tightly and is removed more easily.</strong> The reaction involves losing an electron, and IE drops going down group 1A."},
{chId:'trends',ch:'Periodic Trends',q:"Using Z<sub>eff</sub> = Z - S (S = core electrons), what effective nuclear charge does a chlorine valence electron feel?",o:["+7","+17","+10","+1","+8"],a:0,lec:'Formula sheet: Zeff = Z - S',e:"<div class='math-block'>Z = 17 protons; core electrons ([Ne]) = 10<br>Z<sub>eff</sub> = 17 - 10 = <strong>+7</strong></div>Compare sodium: 11 - 10 = +1. Same shielding core, very different pull. That is why Cl is smaller and holds its electrons harder than Na."},
{chId:'trends',ch:'Periodic Trends',q:"An element's ionization energies (kJ/mol) are IE<sub>1</sub> = 738, IE<sub>2</sub> = 1451, IE<sub>3</sub> = 7733. Which group is it in?",o:["2A","1A","3A","6A","8A"],a:0,lec:'Video 2: successive ionization energies',e:"The huge jump comes between IE<sub>2</sub> and IE<sub>3</sub>, so <strong>the third electron is a core electron</strong> and the element has 2 valence electrons: <strong>group 2A</strong> (this is Mg). His sodium example jumps right after IE<sub>1</sub> (496 &rarr; 4560), because Na has 1 valence electron."},
{chId:'trends',ch:'Periodic Trends',q:"Compared with its neutral atom, how big is a typical anion?",o:["larger, roughly double the radius","smaller, roughly half the radius","exactly the same size","larger, roughly ten times the radius","smaller, because it has more protons"],a:0,lec:'Video 2: ionic radius',e:"His Video 2 slides: <strong>anion radius approximately doubles</strong> (O 73 &rarr; O<sup>2-</sup> 140 pm), <strong>cation radius approximately halves</strong> (Li 152 &rarr; Li<sup>+</sup> 60 pm). Same protons, more electrons, more repulsion."},
{chId:'trends',ch:'Periodic Trends',q:"Which isoelectronic species is LARGEST: O<sup>2-</sup>, F<sup>-</sup>, Na<sup>+</sup> or Mg<sup>2+</sup>?",o:["O<sup>2-</sup>","F<sup>-</sup>","Na<sup>+</sup>","Mg<sup>2+</sup>","all are the same size"],a:0,lec:'Handout 11 and the Oct 5 lecture',e:"All have 10 electrons. <strong>Fewest protons = weakest pull = largest</strong>: O<sup>2-</sup> has only 8 protons. The same logic as Handout 11 #4B, run the other way."},
{chId:'trends',ch:'Periodic Trends',q:"Which way does METALLIC character increase on the periodic table?",o:["down a group and to the left across a period","up a group and to the right across a period","down a group and to the right","up a group and to the left","it does not change"],a:0,lec:'Video 2: metallic character',e:"His summary: metallic character <strong>increases down a column</strong> (ionization energy decreases) and <strong>decreases across a row</strong> (ionization energy increases). Most metallic corner: bottom left (Cs, Fr)."},

// ===== 9. Bonds, electronegativity, polarity =====
{chId:'bonds',ch:'Bonds and Polarity',q:"Match each bond type to its description: ionic, covalent, metallic.",o:["ionic: attraction between cations and anions; covalent: sharing valence electrons; metallic: a 'sea' of electrons around metal atoms","ionic: sharing electrons; covalent: transferring electrons; metallic: attraction between anions","ionic: a sea of electrons; covalent: attraction between ions; metallic: sharing electrons","all three involve sharing valence electrons equally","ionic: between two nonmetals; covalent: between two metals; metallic: between a metal and a nonmetal"],a:0,lec:'Oct 5 and 7 lectures: summary of bond types',e:"His summary slide: <strong>ionic = attraction between cations and anions</strong>; <strong>covalent = sharing of valence electrons</strong>; <strong>metallic = electrons 'float' around metal atoms as a sea of electrons</strong>. Ionic forms between a metal and a nonmetal; covalent between nonmetals."},
{chId:'bonds',ch:'Bonds and Polarity',q:"In a covalent bond, what holds the two atoms together?",o:["the shared electrons are attracted to both nuclei at once","the two nuclei attract each other","the electrons are transferred from one atom to the other","the atoms have opposite charges","a sea of delocalized electrons"],a:0,lec:'Oct 5 lecture: forces behind a covalent bond',e:"His tug-of-war slide: <strong>the electron pair is attracted to both nuclei</strong>. In H<sub>2</sub>, the two 1s orbitals touch, then overlap, and the shared pair forms the bond."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Chapter 4 Worksheet #1. Which compound has IONIC bonding?",o:["KBr","IBr<sub>3</sub>","SeF<sub>6</sub>","P<sub>2</sub>O<sub>5</sub>","Se<sub>2</sub>Cl<sub>2</sub>Br"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"<strong>KBr = metal + nonmetal = ionic</strong> (potassium bromide). The other four are nonmetals only, so covalent: iodine tribromide, selenium hexafluoride, diphosphorus pentoxide, and a ternary compound he says we will not name."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Chapter 4 Worksheet #1. How does his key classify PbS<sub>2</sub>?",o:["ionic: lead is a metal, so it is lead(IV) sulfide","covalent: lead is in the p block, so it is lead disulfide","covalent: it has two sulfur atoms","ionic: it is lead(II) sulfide","it has both ionic and covalent bonds"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"His key: <strong>some elements at the bottom left of the p block are metals, so we indicate the charge</strong>. Pb is a metal: ionic. Two S<sup>2-</sup> give -4, so Pb is +4: <strong>lead(IV) sulfide</strong>. Note his two tools: for a whole compound, metal + nonmetal = ionic (how his key fills the ionic/covalent column); the &Delta;&chi; continuum is for classifying a single bond when you are given &chi; values."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Chapter 4 Worksheet #1. What kind of bonding does Na<sub>2</sub>SO<sub>4</sub> have?",o:["both: ionic between Na<sup>+</sup> and SO<sub>4</sub><sup>2-</sup>, covalent inside the sulfate ion","ionic only","covalent only","metallic","none, it is an element"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"His key: <strong>this species has both</strong>. The Na<sup>+</sup> ions attract the SO<sub>4</sub><sup>2-</sup> ion (ionic), while the S and O atoms inside the polyatomic ion share electrons (covalent). Same for Ca(OH)<sub>2</sub>."},
{chId:'bonds',ch:'Bonds and Polarity',q:"What is electronegativity?",o:["the ability of an atom in a bond to attract the shared electrons toward itself","the energy needed to remove an electron from a gaseous atom","the energy released when an atom gains an electron","the charge on an ion","the size of an atom"],a:0,lec:'Oct 7 lecture: electronegativity',e:"<strong>Electronegativity (&chi;) = how strongly an atom in a bond pulls the shared electrons.</strong> Do not confuse it with ionization energy (removing an electron) or electron affinity (adding one to an isolated atom)."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Which way does electronegativity increase?",o:["up a group and from left to right across a period","down a group and from right to left","down a group and from left to right","up a group and from right to left","it is the same for every element"],a:0,lec:'Oct 7 lecture: trends in electronegativity',e:"His key: <strong>electronegativity increases up a group and from left to right across a row</strong>. Most electronegative: <strong>F (4.0)</strong>. Least: <strong>Fr (0.7)</strong>. Noble gases are usually left out."},
{chId:'bonds',ch:'Bonds and Polarity',q:"The study guide says to memorize four electronegativity values (NClOF). Which set is right?",o:["N 3.0, Cl 3.0, O 3.5, F 4.0","N 3.5, Cl 3.0, O 3.0, F 4.0","N 3.0, Cl 3.5, O 3.0, F 4.0","N 2.5, Cl 3.0, O 3.5, F 4.0","N 3.0, Cl 3.0, O 4.0, F 3.5"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"His mnemonic <strong>NClOF</strong>: the four most electronegative atoms, <strong>N 3.0, Cl 3.0, O 3.5, F 4.0</strong>. N and Cl tie. These will NOT be on the formula sheet."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Chapter 4 Worksheet #2. Rank from LEAST to MOST electronegative: Ca, F, Mg, S.",o:["Ca &lt; Mg &lt; S &lt; F","F &lt; S &lt; Mg &lt; Ca","Mg &lt; Ca &lt; S &lt; F","Ca &lt; S &lt; Mg &lt; F","S &lt; Ca &lt; Mg &lt; F"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"His key: <strong>Ca &lt; Mg &lt; S &lt; F</strong>. Ca is below Mg (less electronegative); S is far right in period 3; F is the most electronegative element."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Chapter 4 Worksheet #3. Which bond is the MOST polar? (C 2.5, F 4.0, H 2.1, N 3.0)",o:["H-F","F-F","N-F","C=N","they are equally polar"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"<div class='math-block'>H-F: 4.0 - 2.1 = 1.9 &nbsp; N-F: 1.0 &nbsp; C=N: 0.5 &nbsp; F-F: 0</div>His key: <strong>as the difference in electronegativity increases, the bond becomes more polar</strong>. H-F wins."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Chapter 4 Worksheet #4. Which bond is the STRONGEST: F-F, H-F, N-F or C=N?",o:["C=N","H-F","F-F","N-F","they are equally strong"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"His key circles <strong>C=N</strong>: it is a <strong>double bond</strong>, two shared pairs, while the others are single bonds. Most polar (H-F) and strongest are different questions."},
{chId:'bonds',ch:'Bonds and Polarity',q:"On his bond-type continuum, which electronegativity difference (&Delta;&chi;) gives a POLAR covalent bond?",o:["between 0.4 and 2.0","between 0 and 0.4","above 2.0","exactly 0","above 3.3"],a:0,lec:'Oct 7 lecture: continuum of bond types',e:"His continuum slide: <strong>0 to 0.4 pure (nonpolar) covalent, electrons shared equally</strong>; <strong>0.4 to 2.0 polar covalent, shared unequally</strong>; <strong>above 2.0 ionic, electrons transferred</strong> (the scale runs to 3.3)."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Classify the O-H bond (O 3.5, H 2.1).",o:["polar covalent (&Delta;&chi; = 1.4)","nonpolar covalent (&Delta;&chi; = 1.4)","ionic (&Delta;&chi; = 1.4)","nonpolar covalent (&Delta;&chi; = 0)","ionic (&Delta;&chi; = 5.6)"],a:0,lec:'Oct 7 lecture: continuum of bond types',e:"<div class='math-block'>&Delta;&chi; = 3.5 - 2.1 = 1.4 &rarr; between 0.4 and 2.0 &rarr; polar covalent</div>The O end is electron-rich (&delta;-), the H end electron-poor (&delta;+). Subtract, never add."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Classify the K-F bond (K 0.8, F 4.0).",o:["ionic (&Delta;&chi; = 3.2)","polar covalent (&Delta;&chi; = 3.2)","nonpolar covalent (&Delta;&chi; = 0.8)","polar covalent (&Delta;&chi; = 1.2)","metallic"],a:0,lec:'Oct 7 lecture: continuum of bond types',e:"<div class='math-block'>&Delta;&chi; = 4.0 - 0.8 = 3.2 &gt; 2.0 &rarr; ionic</div>Metal plus nonmetal gives a large difference: the electron is transferred, not shared."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Classify the Cl-Cl bond.",o:["nonpolar covalent: &Delta;&chi; = 0, electrons shared equally","polar covalent: chlorine is very electronegative","ionic: Cl forms Cl<sup>-</sup>","metallic","polar covalent: &Delta;&chi; = 3.0"],a:0,lec:'Oct 7 lecture: continuum of bond types',e:"Two identical atoms pull equally, so <strong>&Delta;&chi; = 3.0 - 3.0 = 0, nonpolar (pure) covalent</strong>. High electronegativity alone does not make a bond polar; the DIFFERENCE does."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Classify the C-Cl bond (C 2.5, Cl 3.0).",o:["polar covalent (&Delta;&chi; = 0.5)","nonpolar covalent (&Delta;&chi; = 0.5)","ionic (&Delta;&chi; = 5.5)","nonpolar covalent (&Delta;&chi; = 0)","ionic (&Delta;&chi; = 0.5)"],a:0,lec:'Oct 7 lecture: continuum of bond types',e:"<div class='math-block'>&Delta;&chi; = 3.0 - 2.5 = 0.5 &rarr; just past 0.4 &rarr; polar covalent</div>Close to the line, so do the subtraction rather than eyeballing it."},
{chId:'bonds',ch:'Bonds and Polarity',q:"In the H-Cl bond, where are the partial charges?",o:["Cl is &delta;- (electron-rich) and H is &delta;+ (electron-poor)","H is &delta;- and Cl is &delta;+","both atoms are neutral","H carries a full +1 and Cl a full -1","the charges switch back and forth"],a:0,lec:'Oct 9 lecture: electron distribution in HCl',e:"Cl (3.0) is more electronegative than H (2.1), so the shared pair sits closer to Cl. His slide: <strong>Cl end electron-rich, H end electron-poor; H-Cl is a polar covalent bond</strong>. Partial charges (&delta;), not full ones; it is not ionic."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Using E &prop; q<sub>1</sub>q<sub>2</sub>/r from the formula sheet, which pair of ions attracts most strongly?",o:["Mg<sup>2+</sup> and O<sup>2-</sup>","Na<sup>+</sup> and Cl<sup>-</sup>","K<sup>+</sup> and Br<sup>-</sup>","Na<sup>+</sup> and F<sup>-</sup>","Cs<sup>+</sup> and I<sup>-</sup>"],a:0,lec:'Formula sheet: E &prop; q1q2/r',e:"The attraction grows with the <strong>product of the charges</strong> and shrinks with <strong>distance</strong>. Mg<sup>2+</sup>/O<sup>2-</sup> has a charge product of 4 (the others have 1) and both ions are small. Cs<sup>+</sup>/I<sup>-</sup> is the weakest: charge product 1 and the biggest ions."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Which is an element made of molecules, but NOT a compound?",o:["H<sub>2</sub>","NaCl","H<sub>2</sub>O","CO<sub>2</sub>","glucose"],a:0,lec:'Oct 7 lecture: organization of matter',e:"His chart: <strong>H<sub>2</sub> is a diatomic element</strong>, a molecule made of one kind of atom. A compound needs two or more different elements. NaCl is an ionic compound; H<sub>2</sub>O, CO<sub>2</sub> and glucose are molecular compounds."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Which is a POLYATOMIC ion?",o:["NO<sub>3</sub><sup>-</sup>","Cl<sup>-</sup>","Na<sup>+</sup>","O<sub>2</sub>","Mg"],a:0,lec:'Handout 12: polyatomic ions',e:"Handout 12: <strong>a polyatomic ion is an ion of 2 or more covalently bonded atoms</strong>. NO<sub>3</sub><sup>-</sup> (nitrate) qualifies. Cl<sup>-</sup> and Na<sup>+</sup> are monatomic ions; O<sub>2</sub> is a neutral molecule; Mg is an atom."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Classify the N-H bond (N 3.0, H 2.1).",o:["polar covalent (&Delta;&chi; = 0.9)","nonpolar covalent (&Delta;&chi; = 0.9)","ionic (&Delta;&chi; = 0.9)","polar covalent (&Delta;&chi; = 5.1)","ionic (&Delta;&chi; = 2.1)"],a:0,lec:'Oct 7 lecture: continuum of bond types',e:"<div class='math-block'>&Delta;&chi; = 3.0 - 2.1 = 0.9 &rarr; 0.4 to 2.0 &rarr; polar covalent</div>N is &delta;-, H is &delta;+."},

// ===== 10. Naming ions and compounds =====
{chId:'names',ch:'Naming Compounds',q:"Name the ion Cr<sup>3+</sup>.",o:["chromium(III) ion","chromium ion","chromide ion","chromous ion","chromium(II) ion"],a:0,lec:'Oct 9 lecture: nomenclature of ions',e:"Transition metals take their <strong>charge as a Roman numeral in parentheses</strong>, then 'ion': <strong>chromium(III) ion</strong>. Its older name is chromic ion: <strong>-ous = lower charge (Cr<sup>2+</sup>, chromous), -ic = higher charge (Cr<sup>3+</sup>, chromic)</strong>."},
{chId:'names',ch:'Naming Compounds',q:"Name the ion formed by nitrogen, N<sup>3-</sup>.",o:["nitride ion","nitrate ion","nitrite ion","nitrogen ion","nitrogen(III) ion"],a:0,lec:'Oct 9 lecture: monatomic anions',e:"Monatomic nonmetal anions: <strong>replace the ending with -ide</strong>. N<sup>3-</sup> = nitride. His table: C<sup>4-</sup> carbide, N<sup>3-</sup> nitride, O<sup>2-</sup> oxide, F<sup>-</sup> fluoride; Si<sup>4-</sup> silicide, P<sup>3-</sup> phosphide, S<sup>2-</sup> sulfide, Cl<sup>-</sup> chloride. Nitrate and nitrite are polyatomic."},
{chId:'names',ch:'Naming Compounds',q:"What charge do the monatomic ions of the NONMETALS in groups 4A, 5A, 6A and 7A carry?",o:["-4, -3, -2, -1","+4, +5, +6, +7","-1, -2, -3, -4","+4, +3, +2, +1","0 for all of them"],a:0,lec:'Oct 9 lecture: monatomic anions',e:"Nonmetals gain enough electrons to match the next noble gas: <strong>4A -4, 5A -3, 6A -2, 7A -1</strong>. Metals in 1A, 2A and 3A lose 1, 2 and 3 for +1, +2, +3."},
{chId:'names',ch:'Naming Compounds',q:"Give the formula and charge of the AMMONIUM ion.",o:["NH<sub>4</sub><sup>+</sup>","NH<sub>3</sub>","NH<sub>4</sub><sup>-</sup>","NO<sub>3</sub><sup>-</sup>","H<sub>3</sub>O<sup>+</sup>"],a:0,lec:'Handout 12: polyatomic ions',e:"<strong>Ammonium = NH<sub>4</sub><sup>+</sup></strong>, one of the nine he says to memorize, and the only common polyatomic CATION besides hydronium (H<sub>3</sub>O<sup>+</sup>). NH<sub>3</sub> is ammonia, a neutral molecule."},
{chId:'names',ch:'Naming Compounds',q:"Give the formula and charge of the PHOSPHATE ion.",o:["PO<sub>4</sub><sup>3-</sup>","PO<sub>3</sub><sup>3-</sup>","PO<sub>4</sub><sup>2-</sup>","P<sup>3-</sup>","HPO<sub>4</sub><sup>-</sup>"],a:0,lec:'Handout 12: polyatomic ions',e:"<strong>Phosphate = PO<sub>4</sub><sup>3-</sup></strong>. P<sup>3-</sup> is phosphide. HPO<sub>4</sub><sup>2-</sup> (hydrogen phosphate) is on his table but not on the memorize list."},
{chId:'names',ch:'Naming Compounds',q:"Give the formula and charge of the ACETATE ion.",o:["C<sub>2</sub>H<sub>3</sub>O<sub>2</sub><sup>-</sup>","CO<sub>3</sub><sup>2-</sup>","C<sub>2</sub>H<sub>3</sub>O<sub>2</sub><sup>2-</sup>","CH<sub>3</sub><sup>+</sup>","C<sub>2</sub>O<sub>4</sub><sup>2-</sup>"],a:0,lec:'Handout 12: polyatomic ions',e:"<strong>Acetate = C<sub>2</sub>H<sub>3</sub>O<sub>2</sub><sup>-</sup></strong> (charge -1). CO<sub>3</sub><sup>2-</sup> is carbonate."},
{chId:'names',ch:'Naming Compounds',q:"Which name-formula pair is CORRECT?",o:["chlorate = ClO<sub>3</sub><sup>-</sup>","chlorate = ClO<sub>4</sub><sup>-</sup>","sulfate = SO<sub>3</sub><sup>2-</sup>","nitrate = NO<sub>2</sub><sup>-</sup>","hydroxide = OH<sup>2-</sup>"],a:0,lec:'Handout 12: polyatomic ions',e:"<strong>Chlorate ClO<sub>3</sub><sup>-</sup></strong>. ClO<sub>4</sub><sup>-</sup> is perchlorate; SO<sub>3</sub><sup>2-</sup> is sulfite (sulfate is SO<sub>4</sub><sup>2-</sup>); NO<sub>2</sub><sup>-</sup> is nitrite (nitrate is NO<sub>3</sub><sup>-</sup>); hydroxide is OH<sup>-</sup>."},
{chId:'names',ch:'Naming Compounds',q:"Give the formula and charge of the CARBONATE ion.",o:["CO<sub>3</sub><sup>2-</sup>","CO<sub>3</sub><sup>-</sup>","CO<sub>2</sub><sup>2-</sup>","HCO<sub>3</sub><sup>2-</sup>","C<sup>4-</sup>"],a:0,lec:'Handout 12: polyatomic ions',e:"<strong>Carbonate = CO<sub>3</sub><sup>2-</sup></strong>. Hydrogen carbonate (bicarbonate) is HCO<sub>3</sub><sup>-</sup>, and C<sup>4-</sup> is carbide."},
{chId:'names',ch:'Naming Compounds',q:"Order these by number of oxygens, fewest first: chlorate, hypochlorite, perchlorate, chlorite.",o:["hypochlorite (ClO<sup>-</sup>), chlorite (ClO<sub>2</sub><sup>-</sup>), chlorate (ClO<sub>3</sub><sup>-</sup>), perchlorate (ClO<sub>4</sub><sup>-</sup>)","chlorite, hypochlorite, chlorate, perchlorate","perchlorate, chlorate, chlorite, hypochlorite","chlorate, chlorite, perchlorate, hypochlorite","hypochlorite, chlorate, chlorite, perchlorate"],a:0,lec:'Oct 9 lecture: naming an oxyanion',e:"His rule: <strong>-ate has more oxygens than -ite</strong>; with more than two options, <strong>per- has the most and hypo- the least</strong>. All four carry -1. By the same pattern, hypobromite is BrO<sup>-</sup>."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #1. Name Co<sub>2</sub>S<sub>3</sub>.",o:["cobalt(III) sulfide","cobalt(II) sulfide","dicobalt sulfide","cobalt sulfide","cobalt(III) sulfate"],a:0,lec:'Handout 12 and the Oct 9 lecture',e:"<div class='math-block'>3 S<sup>2-</sup> = -6 total &rarr; 2 Co must total +6 &rarr; each Co is +3</div><strong>cobalt(III) sulfide</strong>. Ionic compounds never use prefixes. Sulfate would be SO<sub>4</sub><sup>2-</sup>, not S<sup>2-</sup>."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #1. Write the formula for ammonium carbonate.",o:["(NH<sub>4</sub>)<sub>2</sub>CO<sub>3</sub>","NH<sub>4</sub>CO<sub>3</sub>","NH<sub>4</sub>(CO<sub>3</sub>)<sub>2</sub>","(NH<sub>3</sub>)<sub>2</sub>CO<sub>3</sub>","NH<sub>4</sub>C"],a:0,lec:'Handout 12 and the Oct 9 lecture',e:"NH<sub>4</sub><sup>+</sup> and CO<sub>3</sub><sup>2-</sup>: you need <strong>two ammoniums to balance one carbonate</strong>. Use parentheses for more than one polyatomic ion: <strong>(NH<sub>4</sub>)<sub>2</sub>CO<sub>3</sub></strong>, his smelling-salts example."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #1. Name CaCO<sub>3</sub>.",o:["calcium carbonate","calcium(II) carbonate","calcium tricarbonate","calcium carbide","calcium carbon trioxide"],a:0,lec:'Handout 12 and the Oct 9 lecture',e:"Ca<sup>2+</sup> + CO<sub>3</sub><sup>2-</sup>: <strong>calcium carbonate</strong> (Tums). Group 2A metals have only one possible charge, so <strong>no Roman numeral</strong>."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #5b. Iron reacts with chlorine to form FeCl<sub>3</sub>. Name it.",o:["iron(III) chloride","iron chloride","triiron chloride","iron(II) chloride","ferrous chloride"],a:0,lec:'Handout 12: naming ionic compounds',e:"3 Cl<sup>-</sup> = -3, so Fe is +3: <strong>iron(III) chloride</strong> (older name ferric chloride; ferrous is Fe<sup>2+</sup>). Prefixes like 'tri' are for molecular compounds only."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #5a. What compound forms from K and I?",o:["KI, potassium iodide","KI<sub>2</sub>, potassium diiodide","K<sub>2</sub>I, dipotassium iodide","KI, potassium(I) iodide","KI, potassium iodine"],a:0,lec:'Handout 12: naming ionic compounds',e:"K<sup>+</sup> and I<sup>-</sup> balance one to one: <strong>KI, potassium iodide</strong>. No Roman numeral for a group 1A metal, and the anion takes -ide."},
{chId:'names',ch:'Naming Compounds',q:"Chapter 4 Worksheet #1. Name CrO<sub>3</sub> by his rules.",o:["chromium(VI) oxide","chromium(III) oxide","trichromium oxide","chromium oxide","chromium(II) oxide"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"<div class='math-block'>3 O<sup>2-</sup> = -6 &rarr; one Cr = +6</div><strong>chromium(VI) oxide</strong>. His key: always show a transition metal's charge, and the oxide takes no prefix. (Pb and Sn take numerals too, as in lead(IV) sulfide. 'Chromium trioxide' is a common name you may see elsewhere, but it is not his convention for an ionic compound.)"},
{chId:'names',ch:'Naming Compounds',q:"Chapter 4 Worksheet #6c. What is the charge on vanadium in V<sub>2</sub>S<sub>5</sub>?",o:["+5","+2","+10","+3","-5"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"<div class='math-block'>2V + 5S = 0 &rarr; 2V + 5(-2) = 0 &rarr; 2V = +10 &rarr; V = +5</div>His key: the +10 is split over 2 V ions. Name: vanadium(V) sulfide. +10 is the total, not each ion's charge."},
{chId:'names',ch:'Naming Compounds',q:"Chapter 4 Worksheet #6a. What is the charge on chromium in CrBr<sub>2</sub>?",o:["+2","+1","-2","+4","+3"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"<div class='math-block'>Cr + 2(-1) = 0 &rarr; Cr = +2</div>Cation first, anion second, and the charges must sum to zero. Name: <strong>chromium(II) bromide</strong>."},
{chId:'names',ch:'Naming Compounds',q:"Write the formula for magnesium phosphate.",o:["Mg<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub>","MgPO<sub>4</sub>","Mg<sub>2</sub>(PO<sub>4</sub>)<sub>3</sub>","Mg<sub>3</sub>P<sub>2</sub>","Mg(PO<sub>4</sub>)<sub>2</sub>"],a:0,lec:'Handout 12: naming ionic compounds',e:"<div class='math-block'>Mg<sup>2+</sup> and PO<sub>4</sub><sup>3-</sup> &rarr; least common multiple 6 &rarr; 3 Mg (+6), 2 PO<sub>4</sub> (-6)</div><strong>Mg<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub></strong>. Mg<sub>3</sub>P<sub>2</sub> is magnesium phosphide."},
{chId:'names',ch:'Naming Compounds',q:"Name Ca(OH)<sub>2</sub>.",o:["calcium hydroxide","calcium trihydroxide","calcium(II) hydroxide","calcium oxide hydride","calcium hydrogen oxide"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"Ca<sup>2+</sup> + 2 OH<sup>-</sup>: <strong>calcium hydroxide</strong>. The subscript after the parentheses is never turned into a prefix in an ionic name."},
{chId:'names',ch:'Naming Compounds',q:"Name NH<sub>4</sub>NO<sub>3</sub>.",o:["ammonium nitrate","ammonia nitrate","nitrogen tetrahydride nitrate","ammonium nitrite","ammonium nitride"],a:0,lec:'Handout 12: polyatomic ions',e:"Two polyatomic ions, both on his memorize list: NH<sub>4</sub><sup>+</sup> <strong>ammonium</strong> and NO<sub>3</sub><sup>-</sup> <strong>nitrate</strong>. Nitrite is NO<sub>2</sub><sup>-</sup>; nitride is N<sup>3-</sup>."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #2. Name PCl<sub>5</sub> by his rules.",o:["phosphorus pentachloride","phosphorus tetrachloride","monophosphorus pentachloride","phosphorus chloride","pentachlorophosphide"],a:0,lec:'Handout 12: naming molecular compounds',e:"Two nonmetals = molecular, so use prefixes: <strong>phosphorus pentachloride</strong>. Never put mono- on the FIRST element. Roman numerals are for ionic compounds with variable-charge metals. You will also see 'phosphorus(V) chloride' (OpenStax uses it in a later chapter), but on his exam molecular compounds take prefixes."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #2. Write the formula for diarsenic trisulfide.",o:["As<sub>2</sub>S<sub>3</sub>","As<sub>3</sub>S<sub>2</sub>","As<sub>2</sub>(SO<sub>4</sub>)<sub>3</sub>","AsS<sub>3</sub>","As<sub>2</sub>S<sub>3</sub><sup>2-</sup>"],a:0,lec:'Handout 12: naming molecular compounds',e:"<strong>di = 2 As, tri = 3 S: As<sub>2</sub>S<sub>3</sub></strong>. For molecular compounds the prefixes ARE the subscripts. No charge balancing."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #2. Write the formula for iodine monobromide.",o:["IBr","I<sub>2</sub>Br","IBr<sub>2</sub>","I(Br)","BrI<sub>2</sub>"],a:0,lec:'Handout 12: naming molecular compounds',e:"No prefix on iodine = 1; mono = 1 bromine: <strong>IBr</strong>. Mono- appears only on the second element."},
{chId:'names',ch:'Naming Compounds',q:"Name N<sub>2</sub>O<sub>4</sub>.",o:["dinitrogen tetroxide","trinitrogen tetroxide","nitrogen dioxide","dinitrogen pentoxide","nitrogen oxide"],a:0,lec:'Oct 9 lecture: naming binary molecular compounds',e:"His slide: <strong>dinitrogen tetroxide</strong> (a hypergolic compound). The 'a' of tetra drops before 'oxide'. His other examples: NO nitrogen monoxide, NO<sub>2</sub> nitrogen dioxide, N<sub>2</sub>O dinitrogen monoxide."},
{chId:'names',ch:'Naming Compounds',q:"Name N<sub>2</sub>O (laughing gas).",o:["dinitrogen monoxide","nitrogen dioxide","nitrogen monoxide","dinitrogen dioxide","nitrous dioxide"],a:0,lec:'Oct 9 lecture: naming binary molecular compounds',e:"<strong>di</strong>nitrogen <strong>mon</strong>oxide. Mono- IS used on the second element (and the 'o' of mono drops before 'oxide'). Its common name is nitrous oxide."},
{chId:'names',ch:'Naming Compounds',q:"Which prefix means 7?",o:["hepta","hexa","octa","nona","penta"],a:0,lec:'Handout 12: prefixes',e:"Memorize 1 to 10: <strong>mono, di, tri, tetra, penta, hexa, hepta, octa, nona, deca</strong>. Hexa = 6, octa = 8, nona = 9."},
{chId:'names',ch:'Naming Compounds',q:"Which prefix means 9?",o:["nona","octa","deca","hepta","hexa"],a:0,lec:'Handout 12: prefixes',e:"<strong>nona = 9</strong>, deca = 10, octa = 8. Example: P<sub>4</sub>S<sub>10</sub> is tetraphosphorus decasulfide."},
{chId:'names',ch:'Naming Compounds',q:"Name SF<sub>6</sub>.",o:["sulfur hexafluoride","monosulfur hexafluoride","sulfur pentafluoride","sulfur heptafluoride","sulfide hexafluorine"],a:0,lec:'Handout 12: naming molecular compounds',e:"Molecular: <strong>sulfur hexafluoride</strong>. No mono- on the first element; hexa = 6. His key's twin: SeF<sub>6</sub> = selenium hexafluoride."},
{chId:'names',ch:'Naming Compounds',q:"Name CO.",o:["carbon monoxide","monocarbon monoxide","carbon oxide","carbon dioxide","carbonate"],a:0,lec:'Handout 12: naming molecular compounds',e:"Handout 12 rule 7c: <strong>never use mono- for the first element</strong>. Second element: mono + oxide = monoxide. <strong>Carbon monoxide.</strong>"},
{chId:'names',ch:'Naming Compounds',q:"Why do molecular compounds need prefixes when ionic compounds do not?",o:["nonmetals can combine in many ratios, while ion charges fix an ionic compound's ratio","molecular compounds are always larger","ionic compounds have no subscripts","prefixes show the charges of the ions","prefixes are optional for both"],a:0,lec:'Oct 9 lecture: naming binary molecular compounds',e:"His slide: <strong>molecules can form in many ratios of nonmetals (unlike ionic compounds)</strong>, so 'nitrogen oxide' could mean NO, NO<sub>2</sub>, N<sub>2</sub>O or N<sub>2</sub>O<sub>4</sub>. In ionic compounds the ions combine in a guaranteed ratio: calcium chloride is always CaCl<sub>2</sub>."},
{chId:'names',ch:'Naming Compounds',q:"Chapter 4 Worksheet #1. Name P<sub>2</sub>O<sub>5</sub>.",o:["diphosphorus pentoxide","diphosphorus tetroxide","phosphorus oxide","pentaphosphorus dioxide","phosphate"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"Two nonmetals: <strong>diphosphorus pentoxide</strong>. The 'a' of penta drops before 'oxide'. (His key spells it 'diphosphorous', which is the adjective; the element is phosphorus.)"},
{chId:'names',ch:'Naming Compounds',q:"Name IBr<sub>3</sub>.",o:["iodine tribromide","iodine dibromide","monoiodine tribromide","iodine bromide","triiodine bromide"],a:0,lec:'Chapter 4 Part 1 Review Worksheet',e:"Both nonmetals, so covalent with prefixes: <strong>iodine tribromide</strong>, as in his key."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"An electron in hydrogen moves from n = 1 to n = 3. Using &Delta;E = R<sub>H</sub>(1/n<sub>f</sub><sup>2</sup> - 1/n<sub>i</sub><sup>2</sup>), what do you get, and what does it mean?",o:["-1.94 &times; 10<sup>-18</sup> J: energy was absorbed","+1.94 &times; 10<sup>-18</sup> J: energy was emitted","-1.94 &times; 10<sup>-18</sup> J: energy was emitted","+2.18 &times; 10<sup>-18</sup> J: the electron left the atom","-3.03 &times; 10<sup>-19</sup> J: energy was absorbed"],a:0,lec:'Sep 18 lecture: meaning of signs',e:"<div class='math-block'>&Delta;E = 2.18 &times; 10<sup>-18</sup> J (1/3<sup>2</sup> - 1/1<sup>2</sup>) = 2.18 &times; 10<sup>-18</sup>(0.1111 - 1) = <strong>-1.94 &times; 10<sup>-18</sup> J</strong></div>Negative in his convention = <strong>absorbed</strong>. The photon that was absorbed carried 1.94 &times; 10<sup>-18</sup> J. -3.03 &times; 10<sup>-19</sup> J is the 2 &rarr; 3 jump, (1/9 - 1/4)."},
{chId:'bohr',ch:'Bohr Model and Rydberg',q:"How much energy must be absorbed to remove the electron completely from a hydrogen atom in its ground state (n = 1 to n = &infin;)?",o:["2.18 &times; 10<sup>-18</sup> J","1.64 &times; 10<sup>-18</sup> J","0 J, because 1/&infin;<sup>2</sup> = 0","1.097 &times; 10<sup>7</sup> J","4.36 &times; 10<sup>-18</sup> J"],a:0,lec:'Sep 18 lecture: Rydberg, energy form',e:"<div class='math-block'>n<sub>f</sub> = &infin; so 1/n<sub>f</sub><sup>2</sup> = 0<br>&Delta;E = 2.18 &times; 10<sup>-18</sup>(0 - 1/1<sup>2</sup>) = -2.18 &times; 10<sup>-18</sup> J</div>Negative means absorbed, so <strong>2.18 &times; 10<sup>-18</sup> J</strong> must go in. That is why the energy form of R<sub>H</sub> equals hydrogen's ionization energy per atom. 1.64 &times; 10<sup>-18</sup> J only reaches n = 2."},
{chId:'trends',ch:'Periodic Trends',q:"Which has the higher FIRST ionization energy, N or O?",o:["N, because O's fourth 2p electron is paired and repelled by its partner","O, because ionization energy always increases across a period","they are exactly equal","O, because it has more protons and nothing else matters","N, because N has more electrons"],a:0,lec:'Video 2: ionization energy chart',e:"An exception to the trend, visible on his Video 2 bar chart: <strong>N 1402 vs O 1314 kJ/mol</strong>. N's 2p<sup>3</sup> is half-filled, one electron per orbital. O's fourth 2p electron has to pair up, and the repulsion makes it easier to remove. The same chart shows the other dip: <strong>Be 899 vs B 801</strong>, because B's electron sits alone in a higher-energy 2p."},
{chId:'bonds',ch:'Bonds and Polarity',q:"On a plot of energy versus the distance between two H atoms, what is the bond length?",o:["the distance at the energy minimum, where attraction and repulsion balance","the distance where the energy is highest","the distance where the atoms first touch","zero, because the nuclei merge","any distance where the energy is negative"],a:0,lec:'Oct 5 lecture: forces behind a covalent bond',e:"As the atoms approach, each nucleus attracts the other's electron and the energy drops. Too close, and the two nuclei repel. <strong>The bond length is the distance at the bottom of the energy well</strong>, and the depth of that well is the energy <strong>released</strong> when the bond forms (the same amount must be added to break it)."},
{chId:'bonds',ch:'Bonds and Polarity',q:"Why do crystals of table salt have regular, cube-like shapes?",o:["Na<sup>+</sup> and Cl<sup>-</sup> ions are packed in a regular, repeating crystal lattice","NaCl is made of separate NaCl molecules","the electrons form a sea around the atoms","the crystals are shaped by the container they form in","covalent bonds hold each pair together at fixed angles"],a:0,lec:'Oct 5 lecture: sodium chloride',e:"His slide: <strong>the regular shape of a table salt crystal comes from the regular ordering of ions in a crystal lattice</strong>. An ionic compound has no separate molecules; its formula (NaCl) is the ratio of ions, which is why the particle is called a formula unit."},
{chId:'names',ch:'Naming Compounds',q:"Write the formula for iron(III) oxide.",o:["Fe<sub>2</sub>O<sub>3</sub>","FeO","Fe<sub>3</sub>O","FeO<sub>3</sub>","Fe<sub>3</sub>O<sub>2</sub>"],a:0,lec:'Handout 12: naming ionic compounds',e:"<div class='math-block'>Fe<sup>3+</sup> and O<sup>2-</sup> &rarr; least common multiple 6 &rarr; 2 Fe (+6), 3 O (-6)</div><strong>Fe<sub>2</sub>O<sub>3</sub></strong>. The Roman numeral is the charge of ONE iron ion, not the subscript. FeO is iron(II) oxide."},
{chId:'names',ch:'Naming Compounds',q:"Write the formula for copper(II) sulfate.",o:["CuSO<sub>4</sub>","Cu<sub>2</sub>SO<sub>4</sub>","Cu(SO<sub>4</sub>)<sub>2</sub>","CuS","Cu<sub>2</sub>(SO<sub>4</sub>)<sub>2</sub>"],a:0,lec:'Handout 12: naming ionic compounds',e:"Cu<sup>2+</sup> and SO<sub>4</sub><sup>2-</sup> balance one to one: <strong>CuSO<sub>4</sub></strong>. Always reduce to the lowest ratio, so never Cu<sub>2</sub>(SO<sub>4</sub>)<sub>2</sub>. Cu<sub>2</sub>SO<sub>4</sub> would be copper(I) sulfate, and CuS is copper(II) sulfide."},
{chId:'names',ch:'Naming Compounds',q:"Handout 12 #6 shows a hydrate, CoCl<sub>2</sub>&middot;6H<sub>2</sub>O. What is a hydrate, and what is this one called?",o:["an ionic compound with water molecules attached; cobalt(II) chloride hexahydrate","a molecular compound dissolved in water; cobalt dichloride hexahydride","an ionic compound with water molecules attached; cobalt chloride hexahydroxide","a compound of hydrogen and a metal; cobalt(II) hydride","an acid; hexahydrocobaltic acid"],a:0,lec:'Handout 12: hydrates',e:"Handout 12: <strong>a hydrate is an ionic compound with associated water molecules</strong>. Name the ionic part as usual (2 Cl<sup>-</sup> means Co is +2: cobalt(II) chloride), then add the prefix for the number of waters + 'hydrate': <strong>cobalt(II) chloride hexahydrate</strong>."},
];
